quests[30967] = { id = 30967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreit die Dissidenten", description = "Nicht alle meiner Mitbürger vom Tintenkiemenweiher sind verderbt. Viele von ihnen haben auf meine Warnungen gehört und nicht von dem Sha-verderbten Wasser getrunken.\n\nJedoch leben sie nun in Furcht und müssen sich verstecken, da sie von den Wachen eingeschüchtert werden.\n\nBitte, sagt ihnen, dass es noch Hoffnung gibt! Reist in das Dorf im Norden. Sprecht mit ihnen, und schickt sie zu mir.", sourceObjective = "Rettet 6 Dissidenten der Tintenkiemen am Tintenkiemenweiher.", completion = "Obwohl wir nicht viel herzumachen scheinen, weiß ich aus den glücklosen Anfängen, dass wir es schaffen werden. Danke, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[30968] = { id = 30968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Sha des Hasses", description = "Das Ende unserer Jagd steht unmittelbar bevor. Wir haben die stärksten Shado-Pan versammelt und mit Eurer Stärke als Unterstützung werden wir das Sha des Hasses bezwingen und seinen Einfluss auf die Welt ersticken.\n\nWenn wir in den Tunnel eindringen, bleibt in der Nähe und haltet den Hass von Eurem Herzen fern. Der bevorstehende Kampf stellt für alle von uns eine Prüfung dar.\n\nWas auch immer passieren wird: es ist mir eine Ehre, mit Euch gereist zu sein, {name}.", sourceObjective = "Besiegt das Sha des Hasses.", completion = "Ein Sha zu besiegen... ist nicht einfach. Es ist ein Wunder, dass wir es ohne größere Verletzungen überstanden haben.\n\nTaran gibt sich noch immer die Schuld daran, dass sein Hass die Oberhand gewonnen hat und er diese Bestie auf das Land losgelassen hat. Es mag einige Zeit dauern, bis er sich mit dieser Tatsache anfreunden wird, aber es ist wichtig, dass es irgendwann geschieht. Sonst wird er vielleicht erneut anfällig sein.\n\nHeute haben wir viel erreicht und es wird sobald nicht vergessen werden.\n\nUnd auch Ihr sollt für Euren Beitrag nicht vergessen werden. Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[30969] = { id = 30969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neuer Feind", description = "Die Macht dieser Dunkelschamanen hat viele Verbündete angelockt, {name}. Ehemalige Mitglieder der Horde, die jetzt auf einen finsteren Zweck hinarbeiten.\n\nWir müssen an ihnen ein Exempel statuieren, bevor wir es mit einem weiteren Schattenhammer zu tun bekommen.\n\nTötet alle Kultisten, die Euch über den Weg laufen, und bringt mir ihre Insignien.", sourceObjective = "Sammelt 5 verderbte Insignien von Kultisten im Flammenschlund.", progress = "Habt Ihr die Insignien gesammelt?", completion = "Gut gemacht, {name}. Damit dürfte allen klar sein, wie Garrosh mit Versagern vorzugehen gedenkt...", sourceObjectiveStatus = "unverified-source-field" }
quests[30970] = { id = 30970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Hass erzürnt", description = "Diese Skorpione sind mit Sha infiziert. Es scheint sie aus ihrer Höhle und in unser Lager getrieben zu haben, wo sie die Eindringlinge in ihr Revier ihren sengenden Hass spüren lassen.\n\nWir müssen die Skorpione vernichten und das Lager absichern. Tötet alle, die Ihr findet.", sourceObjective = "Tötet 9 sengende Fleischreißer.", completion = "Gut. Zumindest das, was noch vom Lager übrig ist, ist jetzt sicherer.", sourceObjectiveStatus = "unverified-source-field" }
quests[30971] = { id = 30971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bestandsaufnahme", description = "Ich wurde ins Lager zurückgeschickt, um in Pech getauchte Pfeile für unsere Bogenschützen auf der Brücke zu holen und wurde von dem hier empfangen. Mit den meisten von diesen Pandaren habe ich trainiert... Darauf war ich nicht vorbereitet.\n\nDie Bogenschützen auf der Brücke brauchen trotzdem unsere Hilfe. Wenn Ihr beim Einsammeln von Pfeilen in den Trümmern helft, können wir vielleicht etwas aus diesem Horror herausholen.", sourceObjective = "Sammelt 120 Feuerpfeile der Shado-Pan.", progress = "Die Pandaren auf der Brücke verlassen sich auf uns...", completion = "Ich... Ihr... ähm, danke. Ihr musstet nicht helfen und habt es trotzdem getan. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[30972] = { id = 30972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf in den Kampf", description = "Lao-Chens Bogenschützen unten bei der Brücke werden diese Pfeile brauchen. Könnt Ihr sie ihnen bringen?", sourceObjective = "Bringt den Köcher voll Feuerpfeile der Shado-Pan zu Lao-Chen dem eisernen Bauch an der Dämmerlichtbrücke.", progress = "Willkommen im Chaos.", completion = "Taran Zhu hat mir berichtet, was aus meinem Lager geworden ist. Ich hätte es aufgehalten, wenn ich gekonnt hätte, aber die Angriffe von der Brücke wollten nicht aufhören.\n\nDanke, dass Ihr diese Pfeile bringt - meine Bogenschützen werden sie gut einzusetzen wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30973] = { id = 30973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Flammen aufgehen", description = "Die Mantis, die über die Brücke kommen, haben dicke Panzer, denen die meisten unserer Angriffe nichts anhaben können. Sie haben jedoch eine Schwachstelle: Feuer.\n\nDeshalb haben Lao-Chens Männer Fässer auf das Schlachtfeld gebracht. Werft die Fässer in eine Mantisgruppe, damit Lao-Chens Bogenschützen sie in Brand setzen können.\n\nDanach sollten die Mantis leicht zu erledigen sein.", sourceObjective = "Tötet 10 Holzpanzer der Kor'thik mithilfe von Lao-Chens Fässern.", progress = "Kreative Lösung. Lao-Chen beeindruckt.", completion = "Ein weiterer Vorteil besteht darin, dass die Moral der Mantis darunter leiden wird, wenn sie mit ansehen müssen, wie ihre Brüder verbrennen. Makaber, doch wenn ihr Druck auf unsere Truppen nachlässt, wird das viele Leben retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[30974] = { id = 30974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heben der Stimmung", description = "Die Fässer sind mit dem Schlimmsten aus meinem Lager gefüllt. Gut zum Feuer machen, schlecht zum Trinken.\n\nIch habe aber ein paar Krüge meiner besten Spirituosen herausgeholt und sie mit den Fässern raustragen lassen - sie sind für meine Männer, die sie sie sich wirklich verdient haben! Spirituosen heben nach unendlich langen, zermürbenden Kämpfen die Stimmung.\n\nWärt Ihr wohl so gut und würdet die gute Laune verteilen?", sourceObjective = "Verteilt 8 von Eisenbauchs Spirituosen an Dämmerlichtscharmützler und Dämmerlichtwaldläufer in der Nähe.", sourceObjectiveStatus = "unverified-source-field" }
quests[30975] = { id = 30975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eroberung der Dämmerlichtbrücke", description = "Drängen wir diese Insekten zurück über die Brücke und brechen ihren Kampfgeist!\n\nFolgt mir.", sourceObjective = "Helft Lao-Chen dem eisernen Bauch, die entgegengesetzte Seite der Dämmerlichtbrücke zu halten.", completion = "Nach dieser Abreibung werden die Mantis vermutlich nicht so schnell zurückkommen... und Lao-Chen kann sich uns jetzt bei der Jagd anschließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30976] = { id = 30976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zur Jagd", description = "Damit sind wir um einen Kämpfer stärker. Eure Hilfe ist von unschätzbarem Wert.\n\nLos, brechen wir nach Westen zu Rensais Wachposten auf, um das letzte Mitglied unserer Gruppe zu finden.", sourceObjective = "Reitet mit Taran Zhu, Taoshi und Lao-Chen zu Rensais Wachposten.", completion = "Wir sind ganz nah dran. Ich spüre schon die Wallungen dieses widernatürlichen Hasses.\n\nEs ist nur der Ausbildung der Shado-Pan zu verdanken, dass sie noch nicht von seinem Einfluss überwältigt wurden.", sourceObjectiveStatus = "unverified-source-field" }
quests[30977] = { id = 30977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bodenständige Begrüßung", description = "Alle meiner Männer sind unten im Südwesten bei der Weitblickwarte, um die Mantis abzuwehren, die im Flug die Schlucht zu überqueren suchen. Solange meine Schützen Pfeile haben, bringen sie alle Mantis, die es hinüberschaffen, zum Absturz.\n\nWenn Ihr helfen wollt, könnt Ihr Euch beim Räumen der Mantis nützlich machen, sobald diese am Boden sind. Wärt Ihr dazu bereit, {class}?", sourceObjective = "Tötet 12 abgestürzte Flinkflügel der Kor'thik.", completion = "Ich bin Euch dankbar für Eure Mühen, {class}. Auch die kleinste Verschnaufpause zwischen diesen Angriffen ist heutzutage eine Erleichterung.", sourceObjectiveStatus = "unverified-source-field" }
quests[30978] = { id = 30978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feindliche Lüfte", description = "Gleich geht's ans Eingemachte... \n\nNehmt diese Kanone da und helft, wenn Ihr könnt. An Zielen wird es keinen Mangel geben.", sourceObjective = "Schießt 50 Schwärmer der Kor'thik und Voress'thalik ab.", progress = "Ich könnte Euch wirklich an der Kanone gebrauchen...", completion = "Hervorragend geschossen!\n\nIch bin allerdings ziemlich sicher, dass dieser dicke Käfer den Fall überlebt hat...", sourceObjectiveStatus = "unverified-source-field" }
quests[30979] = { id = 30979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verheerender Schlag", description = "Brechen wir auf, um diesem Riesenkäfer den Garaus zu machen - Ihr und ich.", sourceObjective = "Besiegt Voress'thalik mithilfe des Falkenmeisters Nurong.", completion = "Wo habt Ihr mein ganzes Leben lang gesteckt?! Das war unglaublich!\n\nIch würde jederzeit mit Stolz an Eurer Seite kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30980] = { id = 30980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helden der Shado-Pan", description = "Ihr sagt, Taran Zhu ist in Tonlong und fragt nach mir? Es muss wohl wichtig sein...", sourceObjective = "Kehrt mit Falkenmeister Nurong zu Taran Zhu an Rensais Wachposten zurück.", completion = "Mir gefällt, dass ich mich immer auf Euch verlassen kann. Ihr habt die Einstellung eines echten Shado-Pan.", sourceObjectiveStatus = "unverified-source-field" }
quests[30981] = { id = 30981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taoshi und Korvexxis", description = "Taoshi bereitet einen Überfall auf einen der Mantis-Anführer auf der Südseite von Sik'vess vor. Sie hat den Auftrag, seinen Kristall zu bergen, damit wir mit ihm das Tor öffnen können.\n\nZwei sind stärker als einer. Ich will Euch auch dort haben, damit alles reibungslos über die Bühne geht.", sourceObjective = "Tötet Korvexxis mit Taoshis Hilfe.", completion = "Der erste Kristall gehört uns...", sourceObjectiveStatus = "unverified-source-field" }
quests[30982] = { id = 30982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungezieferbekämpfung", description = "Der Schlund wird von Flammenhunden und Lavawürmern überrannt, und bei solchen Mengen an Troggfleisch als Nahrung können sie sich ewig dort verschanzen.\n\nWir müssen uns sofort um diese Plage kümmern, bevor die Stadt in Gefahr gerät. Ihr seht aus, als könntet Ihr auf Euch aufpassen, {name}.\n\nIch will, dass Ihr Euch einen Weg durch die Bestien bahnt und die größten Bedrohungen ausschaltet: Adarogg und Nagma.", sourceObjective = "Tötet Adarogg und Nagma.", completion = "Gut gemacht, {name}. Wer weiß, was die Biester sonst angerichtet hätten.", sourceObjectiveStatus = "unverified-source-field" }
quests[30983] = { id = 30983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dunkelschamanen", description = "Diese Dunkelschamanen sind schon seit Monaten hier, züchten Bestien und führen dunkle Rituale aus.\n\nIch weiß nicht, was sie mit all dem bezwecken, aber Freunde der Horde sind sie jedenfalls nicht. Und da kommt Ihr ins Spiel, {name}.\n\nKämpft Euch durch den Schlund und tötet Dunkelschamane Koranthal und Lavawache Gordoth.", sourceObjective = "Besiegt Dunkelschamane Koranthal und Lavawache Gordoth.", completion = "Es sieht aus, als hätten die Dunkelschamanenexperimente Gordoth in den Wahnsinn getrieben.\n\nHoffentlich ist der Spuk jetzt zu Ende, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30984] = { id = 30984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Orc bleibt zurück", description = "Es hätte eine Routineaktion sein sollen, {name}. Ein paar Troggs aus dem Weg räumen, sicherstellen, dass keine Gefahr für die Stadt besteht, und mittags nach getaner Arbeit ab in die Taverne.\n\nStattdessen wird eine Gruppe Späher vermisst, Flammenhunde dringen in Massen aus dem Schlund hervor und Xorenth faselt etwas vom \"nächsten Schattenhammer\".\n\n<Kommandant Bagran spuckt aus.>\n\nGeht dort hinein und holt mir meine Späher zurück, damit wir feststellen können, was da unten los ist.", sourceObjective = "Rettet 5 Späher der Kor'kron im Flammenschlund.", completion = "Mehr haben nicht überlebt?\n\nIch weiß nicht, für wen diese Dunkelschamanen arbeiten, aber dafür werden sie bezahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30986] = { id = 30986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die uralte Mogukrypta", description = "Unser Spähtrupp wurde VERNICHTET. Hilfe!", sourceObjective = "Tötet den besessenen Shado-Pan-Anführer und läutert den Teich des Lebens.", sourceObjectiveStatus = "unverified-source-field" }
quests[30987] = { id = 30987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beitritt zur Allianz", description = "Wir haben eine Pflicht, der wir nachkommen müssen, {name}.\n\nEs liegt in unserer Verantwortung, die Tushui-Philosophie über die Grenzen der Wandernden Insel hinaus zu verbreiten... Und es gibt keinen geeigneteren Ort, damit anzufangen, als hier: Sturmwind, das Herz der Allianz.\n\nLasst uns herausfinden, wer hier der Anführer ist. Wir brauchen Verbündete.", sourceObjective = "Sprecht mit König Varian Wrynn in der Burg Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[30988] = { id = 30988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg der Allianz", description = "Ich habe erst vor Kurzem erfahren, dass sich einige Eurer Leute hier einfinden würden. Ich würde Euch gern zu unseren Verbündeten zählen und hoffe, dass Ihr Euch uns anschließt.\n\nBegleitet mich ein Stück, {name}.", sourceObjective = "Begleitet König Varian Wrynn.", sourceObjectiveStatus = "unverified-source-field" }
quests[30989] = { id = 30989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein alter Grubenkämpfer", description = "Ich muss herausfinden, ob Ihr auch wirklich kämpfen könnt. Möglicherweise werden wir beizeiten Eure militärische Hilfe benötigen. Und dann muss ich sicher sein, dass Ihr mein Königreich beschützen könnt.\n\nIch habe viele Geschichten über die Kampftechniken der Pandaren gehört, aber sie noch nie persönlich beobachten dürfen.\n\nAlso? Bereit für einen Kampf?", sourceObjective = "Tragt einen Übungskampf gegen König Varian Wrynn aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[30991] = { id = 30991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Fassrolle machen!", description = "Bei meiner Ausbildung zum Braumeister hätte ich nicht gedacht, dass ich mein Fachwissen einmal auf diese Art einsetzen würde...\n\nHabt Ihr gewusst, dass Bier brennt, wenn man es anzündet? Ja, und wenn man Yaungolöl dazumischt, ist es sogar richtig explosiv.\n\nIch habe das Öl in diese Fässer gemischt. Rollt sie zu den Yaungol drüben am Tor und zündet sie an, wenn Ihr nah dran seid. \n\nEs wird ein paar Sekunden dauern, bis das Fass hochgeht, aber dann...\n\nNa, sagen wir einfach, ich wäre dann nicht gern dabei.\n\nUnd darum werde ich hier bleiben... und den Verlust dieses Bräus betrauern.", sourceObjective = "Nehmt eines der Fässer in der Nähe von Lao-Chen, rollt es den Hügel hinab auf die Yaungol zu und entzündet es in ihrer Nähe, um 4 Baumschleuderer von Osul und 50 Eindringlinge von Osul zu vernichten.", progress = "Hmm? Ich dachte nur gerade an mein armes, armes Bier...", completion = "Jippee, das war vielleicht 'ne Explosion! Und nicht nur eine.\n\nSchade, dass mein Bier dran glauben musste, doch wenigstens sind wir jetzt sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[30992] = { id = 30992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt es zuende!", description = "Wir haben Nachricht von Suna vom Wall erhalten. Irgendetwas geht da vor...\n\nEs sieht so aus, als ob sie sich auf ihren letzten Ansturm vorbereiten. Es wird Zeit, dem eine Ende zu setzen, <mein Freund/meine Liebe>.", sourceObjective = "Beendet die Schlacht um das Ochsentor.", progress = "Lin wurde gefangen genommen... Wir müssen Taran Zhu aus seiner Selbstgefälligkeit reißen!", completion = "Nun, ihr Hauptmann ist tot. Ich glaube, wir haben sie endlich aus Kun-Lai vertrieben.\n\nAber um welchen Preis? So viele Tote, Lin gefangen... Ich werde nicht zulassen, dass Taran Zhu sich weiterhin seiner Verantwortung entzieht.", sourceObjectiveStatus = "unverified-source-field" }
quests[30993] = { id = 30993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist meine Verstärkung?", description = "Das geht jetzt zu weit. Ich kann nicht länger ignorieren, dass wir hier einfach im Stich gelassen werden.\n\nNach allem, was hier geschehen ist und was Ihr in Feuerzweig durchgemacht habt, müssen wir zum Kloster reisen.\n\nEgal, was sie dort beschäftigt hält – es kann warten! Wir können in meinem Ballon den Berg hoch zum Kloster fahren. Er ist beim Lager im Nordosten festgemacht.", sourceObjective = "Sprecht mit Ban Bärenherz außerhalb des Shado-Pan-Klosters am Kun-Lai-Gipfel.", completion = "Da sind wir, und jetzt wisst Ihr, warum wir nicht erlauben können, dass unsere Brüder tatenlos zusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30994] = { id = 30994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lao-Chens Schachzug", description = "In Ordnung. Dank Euch ist die Mauer unter unserer Kontrolle. Gute Arbeit.\n\nIch werde noch etwas hier oben bleiben und sicherstellen, dass es keine weiteren Yaungol auf die Mauer schaffen.\n\nIhr solltet jedoch wieder hinuntersteigen und nachsehen, was sich Lao-Chen ausgedacht hat. Ich gebe es nicht gerne zu, aber vielleicht hat er doch endlich eine gute Idee gehabt...", sourceObjective = "Sprecht mit Lao-Chen dem eisernen Bauch in Winterblüte am Kun-Lai-Gipfel.", completion = "Schön zu sehen, dass Ihr es in einem Stück zurückgeschafft habt. Dank Eurer Hilfe mit den Fässern habe ich es geschafft, eine hübsche Überraschung für unsere Yaungol-Freunde an der Front vorzubereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[30995] = { id = 30995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niemand bleibt zurück", description = "Ich habe vor über einer Stunde einen Aufklärungstrupp ausgesandt, und bislang hat sich noch keiner davon zurückgemeldet. Und jetzt kommen diese verdammten Hunde in Massen aus dem Schlund hervor.\n\nIch weiß nicht, was dort unten vor sich geht, aber ich gehe nirgendwohin, bis ich meine Männer wiederhabe.\n\nIch will, dass Ihr dort hineingeht und sie findet, {name}, vorzugsweise solange sie noch am Leben sind.", sourceObjective = "Rettet 5 Waldläufer des SI:7 im Flammenschlund.", completion = "Mehr haben nicht überlebt?\n\nDas wird die Horde in Blut bezahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30996] = { id = 30996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dunkelschamanen", description = "Diese Dunkelschamanen sind schon seit Monaten hier unten, züchten Bestien und führen dunkle Rituale aus.\n\nIch weiß nicht, was sie mit all dem bezwecken, aber Freunde der Allianz sind sie jedenfalls nicht. Und ich brauche Eure Hilfe, um sie aufzuhalten, {name}. \n\nKämpft Euch durch den Schlund und tötet Dunkelschamane Koranthal und Lavawache Gordoth.", sourceObjective = "Besiegt Dunkelschamane Koranthal und Lavawache Gordoth.", completion = "Es sieht aus, als hätten die Dunkelschamanenexperimente Gordoth in den Wahnsinn getrieben.\n\nHoffentlich ist der Spuk jetzt zu Ende, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30997] = { id = 30997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungezieferbekämpfung", description = "Ich bin froh, dass Ihr hier seid, {name}. Die Horde zieht eine Armee zusammen, und ich werde nicht warten, bis ich den Grund dafür weiß.\n\nWir müssen schnell zuschlagen und ein paar der größeren Bestien erledigen, die sie hier unten haben.\n\nIch will, dass Ihr dort hineingeht und Euch um Adarogg und Nagma kümmert, bevor die Horde sie als Waffen gegen uns einsetzen kann.", sourceObjective = "Tötet Adarogg und Nagma.", completion = "Gut gemacht, {name}. Wer weiß, was die Biester sonst angerichtet hätten.", sourceObjectiveStatus = "unverified-source-field" }
quests[30998] = { id = 30998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neuer Feind", description = "Die Horde nutzt dunkle Magie, um Bestien zu kontrollieren und ihre Brüder hier unten zu verderben, {name}.\n\nDem beabsichtige ich einen Riegel vorzuschieben, aber zunächst muss ich wissen, womit wir es hier überhaupt zu tun haben. Und da kommt Ihr ins Spiel.\n\nKämpft Euch durch die Höhlen und sammelt die Insignien, die die Kultisten bei sich tragen. Damit kann ich feststellen, mit welcher Art von Magie wir es hier zu tun haben.", sourceObjective = "Sammelt 5 verderbte Insignien von den Dunkelschamanenkultisten.", progress = "Habt Ihr die Insignien gesammelt?", completion = "Gut gemacht, {name}. Jetzt können wir herausfinden, was sie hier unten wollten.", sourceObjectiveStatus = "unverified-source-field" }
quests[30999] = { id = 30999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährliche Reise", description = "Die schwierigsten Wege lehren uns oft das meiste, {class}. Ich werde zweifellos sehr viel davon lernen, dem Pfad Shaohaos zu folgen.\n\nVor vielen Jahren bestieg Shaohao den höchsten Gipfel des Kun-Lai-Gebirges, um Rat bei der Jadeschlange einzuholen. Auch ich werde auf der Suche nach Weisheit zum Grat des Unwissenden reisen.\n\nVielleicht seid Ihr ja auch an einer solchen Reise interessiert? Falls dem so ist, sprecht mit Onkel Kleeblatt. Er wird Euch bei Euren Vorbereitungen helfen.", sourceObjective = "Sprecht mit Onkel Kleeblatt in Einfass.", completion = "Die Reise zum Grat des Unwissenden birgt viele Gefahren, {class}. Hoffentlich habt Ihr genug Glücksbringer dabei!", sourceObjectiveStatus = "unverified-source-field" }
quests[31000] = { id = 31000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schreckensort", description = "Shado-Pan-Bogenschützen halten kontinuierlich Wache über die Schreckensöde, von der Spitze des Schlangenrückens aus. Sie würden die Hilfe von jemand so Fähigem wie Euch, {class}, sicher willkommen heißen.\n\nNehmt einen Drachen und meldet Euch bei Bogenmeisterin Li.", sourceObjective = "Sprecht mit Bogenmeisterin Li auf dem Schlangenrücken.", completion = "Ein Freiwilliger für den Dienst in der Schreckensöde? Da dürftet Ihr der erste sein.\n\nFreut mich, Euch kennenzulernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31001] = { id = 31001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Absturz", description = "Die Mantis abzuwehren ist schlimm genug, doch jetzt haben wir auch noch Spinnen, die von den Ruinen dort unten ausschwärmen.\n\nEiner meiner besten Bogenschützen wurde von einem ihrer Netze erfasst und direkt nach unten gezogen!\n\nWir glauben, dass er noch lebt, ich habe jedoch nicht genug Leute, um jemanden zu seiner Rettung loszuschicken. Hier oben sind unsere Ressourcen ausgereizt, {class}.\n\nWenn Ihr helfen wollt, benutzt das Seil hinter mir, um Euch in die Ruinen abzuseilen. Ihr leidet doch nicht etwa unter Höhenangst?\n\nUnd wie steht es mit Spinnen?", sourceObjective = "Seilt Euch mit dem Shado-Pan-Seil zur Terrasse von Gurthan ab und sucht nach dem gestürzten Shado-Pan-Bogenschützen.", completion = "Der Sturz war gar nicht so schlimm. Ich hatte schon immer ein Talent für weiche Landungen.\n\nDass ich auf einem Haufen Spinnenkadaver gelandet bin, hat vermutlich dabei geholfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31002] = { id = 31002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfui Spinne", description = "Wir halten uns, aber nur mit Müh und Not. Was auch immer Ihr anstellt, um den Ansturm der Schreckensspinner zu hemmen, die über die Mauer kommen, wäre eine große Hilfe.\n\nIst Euch danach zumute, Spinneneier einzeln mit der Hand zu öffnen?\n\nHab ich mir auch nicht gedacht. Nehmt eines unserer Drachengewehre und entzündet es dort unten. Ich will die Kleinen knallen hören.", sourceObjective = "Tötet 6 Schreckensspinnerhüter und benutzt das Drachengewehr der Shado-Pan, um 20 Schreckensspinnereier auf der Terrasse von Gurthan zu zerstören.", progress = "Hey, helft mir hier raus!", completion = "Gute Arbeit habt Ihr mit dem Drachengewehr geleistet. Ich habe dort unten mein Bestes gegeben, Pfeile richten gegen diese Dinger allerdings nur begrenzt Schaden an.", sourceObjectiveStatus = "unverified-source-field" }
quests[31003] = { id = 31003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrückte Mantis", description = "Ihr werdet nicht glauben, was ich gesehen habe! Zwei Mantis, die miteinander gekämpft und Magie hin- und hergeschleudert haben.\n\nEiner von ihnen sah anders aus als alle Mantis, die ich je gesehen habe. Völlig andere Farben und Kleidung, wie eine Art... Orakel oder so. Der andere war total verrückt und hat mit Sha-Energie um sich geschmissen, als ob sie ein Krug Sturmbräuspezialmischung wär.\n\nIch muss jetzt zurück zu meinem Posten, aber die zwei kämpfen immer noch in der Höhle hinter mir und ich hab so ein Gefühl, dass es ziemlich wichtig ist. Wollt Ihr Euch das nicht mal anschauen?", sourceObjective = "Untersucht die internen Kämpfe der Mantis auf der Terrasse von Gurthan.", progress = "Die Kaiserin... ist... irregeleitet.", completion = "<Dieser Mantis ist schwer verletzt. Er ringt keuchend nach Atem und kann kaum sprechen.>\n\nHalt, {race}...\n\nWir sind... nicht Euer Feind.", sourceObjectiveStatus = "unverified-source-field" }
quests[31004] = { id = 31004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Bern umhüllt", description = "Nehmt... das...\n\n<Der sterbende Mantis streckt seinen Arm aus. In seinem geschundenen Greifer ruht eine Metallgabel mit zwei langen, dünnen Zinken und einem mit Edelsteinen besetzten Griff.>\n\nErweckt... den Windschnitter...\n\nNur so... kann dem Schwarm ein Ende bereitet werden.", sourceObjective = "Benutzt die Stimmgabel der Klaxxi am uralten Bernbrocken auf der Terrasse von Gurthan.", completion = "Die Klaxxi... rufen mich.", sourceObjectiveStatus = "unverified-source-field" }
quests[31005] = { id = 31005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erweckungskrankheit", description = "Verzeiht meinen derzeitigen... Zustand. Ich habe viele Jahre lang geschlafen.\n\nEin Klaxxi'va mit Kyparisaft hätte meiner Erweckung beiwohnen sollen... aber nun müsst Ihr genügen.\n\nIm Süden spüre ich das Summen von Saftfliegen. Bringt sie zu mir.", sourceObjective = "Bringt 100 Saftfliegenteile zu Kil'ruk dem Windschnitter auf der Terrasse von Gurthan.", progress = "Ohne Nahrung werde ich schon sehr bald sterben.", completion = "Das wird ausreichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31006] = { id = 31006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Rat der Klaxxi", description = "Es ist Zeit, dass ich den Klaxxi Bericht erstatte. Sie hätten mich nicht erweckt, wenn es die Situation nicht verlangen würde.\n\nUnd Ihr habt Euch als nicht vollkommen nutzlos erwiesen. Deshalb werde ich Euch Euer Leben lassen.\n\nDer Rat wird vielleicht sogar noch Verwendung für Euch haben.", sourceObjective = "Reist nach Klaxxi'vess inmitten der Schreckensöde. Ihr könnt Kil'ruk den Windschnitter auf der Terrasse von Gurthan bitten, Euch hinzubringen, oder auf eigene Faust reisen.", completion = "Dies ist ein heiliger Treffpunkt für die Klaxxi.\n\nIhr wärt gut beraten, mir das Reden zu überlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31007] = { id = 31007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schreckensgelege", description = "Die kaiserlichen Gelege sind zu einer Abscheulichkeit verkommen! Gelegehüter treiben die Entwicklung neuer Schwarmgeborener voran, indem sie sie in dieser bösartigen \"Sha\"-Energie tränken, bevor sie sie zur Mauer schicken.\n\nDie Klaxxi wollen dieser massiven Produktion an Schwarmgeborenen in den Schreckensgelegen Einhalt gebieten. Vernichtet die Gelegehüter!", sourceObjective = "Tötet 6 Gelegehüter der Shek'zeer in den Gelegen von Shek'zeer.", completion = "Ein paar Verräter weniger, die wir an die Kunchong verfüttern, wenn sich der Aufruhr gelegt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[31008] = { id = 31008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bernwaffen", description = "Ihr da! Abschaum!\n\nIhr arbeitet jetzt für mich!\n\nDie Waffen der Klingenverschriebenen der Shek'zeer gehören zu den besten im ganzen Reich. Wenn Ihr nicht direkt von ihnen aufgespießt werdet, sobald Ihr diesen Ort verlasst, bringt mir so viele von ihnen, wie Ihr nur könnt! Ich will sicherstellen, dass wir genügend Waffen in Reserve haben, sollten wir sie brauchen.", sourceObjective = "Sammelt 6 Bernklingen von Klingenverschriebenen der Shek'zeer beim Herzen der Angst und in den Gelegen von Shek'zeer.\n\nSprecht mit Kil'ruk dem Windschnitter in Klaxxi'vess für einen Ritt zum Herzen der Angst.", progress = "Die Klingenverschriebenen führen ihre Schwerter mit Stolz. Ich will diese Schwerter in meinen Waffenständern haben.", completion = "Wenn alles nach Plan verläuft, werden die Klaxxi die Kaiserin ohne unsere Hilfe aufhalten. Dennoch ist es meine Rolle, mich bereitzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[31009] = { id = 31009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toter Winkel", description = "Ein Klaxxi'va flüstert dem Turm zu. Dieser verbreitet die Nachricht zu anderen Türmen, zu Mantis, zu Getreuen. Das Geflüster wird zurückgeworfen und die Klaxxi hören es.\n\nSo wissen sie alles.\n\nEin Turm neben dem Palast ist still. Das darf nicht sein. Er muss für die Klaxxi singen.\n\nEs ist meine Aufgabe, den Turm zu reparieren, aber wenn Ihr den Klaxxi dient, solltet Ihr auch mir dienen. Ihr repariert den Turm und ich werde hier warten!", sourceObjective = "Sockelt den Resonanzkristall der Klaxxi in das inaktive Schallrelais beim Herzen der Angst.\n\nSprecht mit Kil'ruk dem Windschnitter in Klaxxi'vess für einen Ritt zum Herzen der Angst.", sourceObjectiveStatus = "unverified-source-field" }
quests[31010] = { id = 31010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In ihren Fängen", description = "Der Kristall singt zu den Klaxxi. Sie spüren einen Getreuen in den Gelegen direkt östlich vom Turm.\n\nGelegehüter versuchen, ihn zu verseuchen. Die Klaxxi werden das nicht zulassen.\n\nGeht und findet den Getreuen. Legt Eure Hände auf seine Kammer, und die Klaxxi werden ihr Flüstern durch Euch kanalisieren, um ihn zu befreien. Schützt ihn, wenn Ihr könnt.", sourceObjective = "Findet und erweckt den Mantisgetreuen in den Gelegen von Shek'zeer.", completion = "Mein Schlaf wurde von plötzlichen Träumen unterbrochen. Unaussprechliche Alpträume.\n\nDann wachte ich auf.\n\nDie Klaxxi haben zu mir gesprochen. Ich habe meine Befehle. Es gibt viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[31011] = { id = 31011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feinde vor den Toren", description = "Die Zandalari greifen an! Ihr müsst bei der Verteidigung des Dorfs helfen!\n\nWenn wir sie nicht zurückschlagen können, werden wir niemals die Überreste des Donnerkönigs finden!", sourceObjective = "Besiegt 10 Berserker der Amani, 5 Ungetüme der Amani und 3 Blutreiter der Gurubashi.", progress = "Das Dorf muss gerettet werden!", completion = "Die Zandalari haben ihren Rückzug begonnen, {name}. Dieser Sieg wird den Dorfbewohnern viel bedeuten.\n\nIn dem Durcheinander ist es mir gelungen, einen der Kämpfer gefangenzunehmen. Vielleicht gibt er ein paar Informationen preis..", sourceObjectiveStatus = "unverified-source-field" }
quests[31012] = { id = 31012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beitritt zur Horde", description = "Da sind wir, {name}... Orgrimmar, das Herz der Horde.\n\nAuch jenseits der Grenzen der Wandernden Insel können wir helfen. Es gibt dort draußen zahllose Probleme, die nur darauf warten, dass wir sie lösen. Meister Shang Xi hätte es so gewollt.\n\nEs gibt keinen besseren Ort, um damit anzufangen, als hier, mit der Hilfe der Horde. Finden wir heraus, wer ihr Anführer ist. Wir brauchen Verbündete.", sourceObjective = "Sprecht mit Garrosh Höllschrei in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[31013] = { id = 31013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg der Horde", description = "Mir wurde kürzlich zugetragen, dass Eure Art hierher kommen könnte.\n\nIch versuche seit Kurzem, die Stärke der Horde zu erhöhen. Einige Pandaren können uns da guttun.\n\nBegleitet mich ein Stück, {name}.", sourceObjective = "Geht mit Garrosh Höllschrei.", sourceObjectiveStatus = "unverified-source-field" }
quests[31014] = { id = 31014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllschreis Geschenk", description = "Ich muss wissen, ob Ihr kämpfen könnt... dass Ihr töten könnt und auch überleben. Am Ende wird jeder von Euch zum Krieg gerufen werden, und ich muss wissen, dass ich auf Euch zählen kann.\n\nIch habe vorhin von einem Geschenk gesprochen. Es ist hier, im Ring der Ehre. Tretet in die Arena, direkt durch diese Tür hinter mir. Ich werde Euer Können prüfen.", sourceObjective = "Beendet Garroshs Prüfung, indem Ihr Oggax, Gadoon und Eisblut besiegt.", completion = "Ihr habt Euren Wert im Kampf und im Herzen mehr als bewiesen. Nur wenige wären bereit, ihre Heimat zu verlassen, um sich der Horde anzuschließen. Noch weniger wären bereit, sich im Kampf einem angreifenden Magnataur zu stellen.\n\nIhr und die anderen aus Eurem Volk sind bei uns willkommen. Willkommen in der Horde, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31015] = { id = 31015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eure Privatsammlung", description = "Pandaria ist ein Land, das reich an Geschichte, Legenden und Wissensschätzen aller Art ist. Ich möchte Euch bitten, auf Eurer Reise durch die Welt nach Artefakten und Informationen, die unserer Arbeit hier dienlich sein könnten, Ausschau zu halten.\n\nWenn Ihr genug Wissen zusammengesammelt habt, werden wir es hier in einem Buch für Eure persönliche Sammlung zusammenfassen.\n\nIhr könnt selbstverständlich gern jederzeit wiederkommen, um die Bücher einzusehen, die wir für Euch zusammenstellen.", sourceObjective = "Füllt das leere und verstaubte Buchregal auf.", progress = "So viel zu lernen.", completion = "Ah! Nun da das erledigt ist, können wir anfangen, Eure gesammelten Forschungsergebnisse zusammenzustellen. Ich freue mich schon darauf, zu sehen, was Ihr gefunden habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31016] = { id = 31016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lehrensucher", sourceObjective = "Sprecht mit Lehrensucher Cho im Heim des Wissens im Tal der Ewigen Blüten.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[31018] = { id = 31018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter dem Herzen der Angst", description = "Die Klaxxi haben einen weiteren Getreuen entdeckt, <Erwecker/Erweckerin>.\n\nDer hier wurde gut vor uns versteckt, und zwar aus gutem Grund.\n\nDie Kaiserin hat ihn bereits in Besitz genommen, und ihre Gehilfen versuchen ihn gerade zu vernichten.\n\nSie wirken ihre Zauber in einer Kammer tief unter dem Palast und müssen aufgehalten werden.\n\nWir halten Klaxxi'vess. Ihr müsst an unserer Statt gehen. Findet den Eingang zu ihrer Kammer beim Sims im Westen.", sourceObjective = "Tötet Gehilfe Ek'vem, Gehilfe Ikkess, Gehilfe Suruz und Gehilfe Tsikzi und befreit anschließend Xaril den vergifteten Geist.", completion = "Ihr habt Eure Pflicht gut erfüllt, Erwecker.", sourceObjectiveStatus = "unverified-source-field" }
quests[31019] = { id = 31019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bern ist Leben", description = "Damit unsere Anstrengungen gegen das Mantisreich fortgesetzt werden können, benötigen wir mehr Bern.\n\nUnterhalb des Sees im Süden gibt es einen großen Vorrat Bern, allerdings wird diese Region von einem wilden Saurokstamm bewohnt.\n\nIch kann sonst niemanden entbehren. Ihr müsst zu dem See gehen und die Stärke des Stammes einer Probe unterziehen. Dünnt ihre Reihen aus und vernichtet ihren Anführer.\n\nDas ist doch sicher keine große Aufgabe für Euch, oder?", sourceObjective = "Tötet 7 Reißer der Nebelklingen und den Schuppenlord der Nebelklingen.", progress = "Der Bern kommt mir irgendwie bekannt vor…", completion = "Das Flüstern scheint diesem Bern zu entströmen.\n\nKann es sein, dass ein weiterer Getreuer darin schläft?", sourceObjectiveStatus = "unverified-source-field" }
quests[31020] = { id = 31020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bestie füttern", description = "Ich muss sofort zum Rat der Klaxxi und den anderen Getreuen, aber ich kann kaum stehen.\n\nIch muss essen, <Erwecker/Erweckerin>.\n\nIch spüre die schlagenden Herzen von Kreaturen am nördlichen Ufer des Sees.\n\nTötet sie für mich und ich erledige den Rest.", sourceObjective = "Tötet 8 Kaltbisskrokilisken.", progress = "Ich habe viele tausende Jahre lang geschlafen. Bevor ich dem Rat erneut beitrete, muss ich an Stärke gewinnen.", completion = "Ich spüre, wie die Kraft in meinen Körper zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31021] = { id = 31021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebendiger Bern", description = "Flüssiger Bern ist höchst effizient, um einen neu erweckten Getreuen zu stärken, und wird normalerweise bei der Erweckungszeremonie bereitgestellt.\n\nLeider scheint es, als ob Ihr diese Anweisungen nicht erhalten habt. Wir müssen also improvisieren.\n\nIch spüre, dass es in dem See unter uns eine große Menge fossilisierten Berns gibt. Es würde mir helfen, aber ich bin zu schwach, es selbst hervorzuholen.\n\nWenn Ihr es für mich tut, sollt Ihr belohnt werden.", sourceObjective = "Sammelt 8 Einheiten lebendigen Berns und gebt sie Korven dem Ersten zu essen.", progress = "Versteht Ihr das, Erwecker? Der Bern ist ein Lebensspender.", completion = "Vielen Dank, Erwecker. Das reicht fürs Erste.", sourceObjectiveStatus = "unverified-source-field" }
quests[31022] = { id = 31022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kypari Zar", description = "Was ist das für ein Baum auf dem Hügel im Westen? Ist es vielleicht... Kypari Zar?\n\n<Korven der Erste verfällt in Schweigen.>\n\nAls ich von meinem letzten Zerstörungszug wiederkam, noch bevor ich zu einem Getreuen erhoben wurde, wurde mir die Ehre zuteil, genau diesen Baum zu pflanzen.\n\nWie ich sehe, ist er zu einem großen Kypari geworden, aber... irgendetwas stimmt nicht.\n\nEs gibt einen alten Sonarturm am Fuß des Baums. Bringt mich dorthin, <Erwecker/Erweckerin>. Ich kann den Turm nutzen, um mir die Sache genauer anzusehen.", sourceObjective = "Aktiviert den Sonarturm und verteidigt anschließend Korven den Ersten, während er den Baum untersucht.", progress = "Was ist mit unserem Zuhause passiert? Es fühlt sich nicht richtig an.", completion = "Einst wurden die Adern dieses Baums von gewaltigen Bernflüssen durchströmt. Jetzt ist er nicht weiter als eine vertrocknete Hülle.", sourceObjectiveStatus = "unverified-source-field" }
quests[31023] = { id = 31023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarmrelikte", description = "Diese merkwürdige Schnitzerei ist mit komplizierten Schriftzeichen bedeckt, die aus der Sprache der Mantis stammen könnten.\n\nEuch fallen weitere Relikte auf, die achtlos über das Lager und im See verstreut liegen.\n\nVielleicht hätten die Klaxxi Interesse daran, diese Artefakte zu untersuchen.\n\nWer weiß? Vielleicht verdient Ihr Euch dadurch einen Gefallen.", sourceObjective = "Sammelt 8 Mantisrelikte.", progress = "Was habt Ihr denn da?", completion = "Diese Relikte beschreiben die Geschichte von Kypari Vos und den Bernbäumen in der Nähe.\n\nIch würde sie gern untersuchen.\n\nVielen Dank, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31024] = { id = 31024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kunchong-Leckereien", description = "Kovok wird größer und muss zu gleichen Teilen diszipliniert und belohnt werden.\n\nAn Disziplin mangelt es mir nicht, doch unsere Fleischvorräte gehen zur Neige.\n\nWeiter im Süden werdet Ihr nördlich des Sternensees und Kypari Zars Schildkröten finden.\n\nMacht Jagd auf sie. Ihr Fleisch schmeckt Kovok.", sourceObjective = "Sammelt 4 fleischige Schildkrötenlenden.", progress = "Was habt Ihr Kovok mitgebracht?", completion = "Ja, ein angemessenes Mahl.\n\nGut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[31026] = { id = 31026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wurzel des Problems", description = "Kypari Zar stirbt.\n\nVon tief unter seinen Wurzeln wird er von einer schrecklich Dunkelheit verderbt.\n\nDer Baum kann nicht gerettet werden, aber wir können zumindest seine Schmerzen lindern.\n\nSchaut. Diese bösartige Kreatur hat einen Pfad zu seinem Versteck geschaffen. Wir müssen ihm nur den Hügel hier hinter dem Turm hinunter folgen.", sourceObjective = "Tötet die Kaltbissmatriarchin.", progress = "Der Schwarm weiß nichts von ihrer schrecklichen Torheit! Diese kostbaren Bäume müssen um jeden Preis geschützt werden!", completion = "Danke, Erwecker. Jetzt kann Kypari Zar in Frieden träumen.\n\nDie Bestie war allerdings nur ein Gefäß für die Verderbnis.\n\nNein... die wahre Verderbnis liegt viel tiefer.", sourceObjectiveStatus = "unverified-source-field" }
quests[31030] = { id = 31030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ins Kloster", description = "Das ist ... unfassbar. Wenn das Kloster wirklich vom Sha übernommen wurde, wird es uns viel abverlangen, die Mönche darin von dem verderblichen Einfluss zu reinigen.\n\nRuft eine Gruppe Eurer Verbündeten zusammen und trefft mich im Kloster.", sourceObjective = "Trefft Ban Bärenherz im Shado-Pan-Kloster.", completion = "Ihr seid gekommen. Gut. Wir befinden uns in einer prekären Situation.", sourceObjectiveStatus = "unverified-source-field" }
quests[31031] = { id = 31031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ins Kloster", description = "Das ist ... unfassbar. Wenn das Kloster wirklich vom Sha übernommen wurde, wird es uns viel abverlangen, die Mönche darin von dem verderblichen Einfluss zu reinigen.\n\nRuft eine Gruppe Eurer Verbündeten zusammen und trefft mich im Kloster.", sourceObjective = "Trefft Ban Bärenherz im Shado-Pan-Kloster.", sourceObjectiveStatus = "unverified-source-field" }
quests[31032] = { id = 31032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ersticken der Himmel", description = "Nurong möchte, dass ich Fackeln zum Verbrennen der Leichen verteile.\n\nDie fliegenden Mantis sind zerbrechlich und werden dem heißen Rauch nicht lange standhalten.", sourceObjective = "Verbrennt 10 Leichen der Flinkflügel der Kor'thik.", progress = "Wenn es auch einige von ihnen durch den Rauch schaffen, sind es nur so wenige, dass wir sie leicht abschießen können.", completion = "Seid bedankt für Eure Hilfe, Fremder.", sourceObjectiveStatus = "unverified-source-field" }
quests[31034] = { id = 31034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feinde im Untergrund", description = "Direkt unter dieser Stadt befinden sich Feinde der Horde, {class}.\n\nDie Dunkelschamanen erheben Anspruch auf Orgrimmar und haben bereits den Flammenschlund eingenommen! Wir müssen ihren Truppen entgegenstürmen und uns das zurückholen, was uns gehört!\n\nGeht und sprecht mit Kommandant Bagran direkt hinter dem Eingang zum Flammenschlund. Er wird weitere Befehle für Euch haben.", sourceObjective = "Sprecht mit Kommandant Bagran.", completion = "Ich habe Euch bereits erwartet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31036] = { id = 31036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feinde im Untergrund", description = "Der Flammenschlund von Orgrimmar ist an die Dunkelschamanen gefallen! {name}, das dürfen wir nicht einfach hinnehmen, sonst gehen sie als Nächstes auf Donnerfels los.\n\nGeht und sprecht mit Kommandant Bagran direkt hinter dem Eingang zum Schlund. Helft ihm, so gut Ihr könnt, denn unsere Schicksale sind miteinander verwoben.", sourceObjective = "Sprecht mit Kommandant Bagran.", sourceObjectiveStatus = "unverified-source-field" }
quests[31037] = { id = 31037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feinde im Untergrund", description = "Mit all seinem üblichen Charme erbittet Kriegshäuptling Garrosh höflichst um Eure Anwesenheit im Flammenschlund, um bei dessen Rückeroberung von den Dunkelschamanen zu helfen. Seine befestigte Stadt ist offenbar nicht ganz so uneinnehmbar, wie er dachte.\n\nGeht und sprecht mit Kommandant Bagran direkt hinter dem Eingang zum Flammenschlund. Er wird sicher froh sein, kompetente Hilfe zu bekommen.", sourceObjective = "Sprecht mit Kommandant Bagran.", completion = "Ich habe Euch bereits erwartet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31038] = { id = 31038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Herausforderers: Schneeblüte", description = "Die Nachrichten von Euren Heldentaten verbreiten sich im Lager, {name}.\n\nSchneeblüte würde Eure Fertigkeit im Kampf gern testen.\n\nBereitet Euch lieber vor, {class}. Sie ist nicht einfach zu besiegen.\n\nWenn Ihr Euer Potenzial unter Beweis stellen könnt, werdet Ihr eine wertvolle Freundin gewinnen.", sourceObjective = "Fordert Schneeblüte heraus und besiegt sie im Ring des Herausforderers.", progress = "Wie ist es gelaufen?", completion = "Ach ja, Ihr habt Schneeblüte also tatsächlich im Kampf besiegt?\n\nIch wette, die Niederlage wird ihr eine Weile lang schwer zu schaffen machen.\n\nIhr habt sie aber auf Eure Seite gebracht - gut gemacht.\n\nSie freundet sich mit Fremden nicht schnell an, wird sich aber mit der Zeit als loyale und zuverlässige Gefährtin erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31039] = { id = 31039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mogubedrohung", description = "Unsere Späher haben Truppen der Mogu auf Shan'ze Dao im Nordwesten entdeckt.\n\nDie Insel ist angeblich unbewohnt, deshalb ist ihre Anwesenheit dort beunruhigend.\n\nNoch beunruhigender ist die Tatsache, dass sie unheimliche Experimente auf der Insel durchführen.\n\nIch brauche jemand Tüchtiges wie Euch, {class}, um die Lage zu prüfen.\n\nDie Shan'ze werden Euch vermutlich Probleme bereiten. Wenn dieser Fall eintritt, tötet sie.", sourceObjective = "Tötet 12 Schlangenbinder oder Bestienmeister der Shan'ze.", completion = "Die Shan'ze führen etwas im Schilde. Gut gemacht, {name}, wir müssen aber weiter im Auge behalten, was sie machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31040] = { id = 31040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boshafte Waldgeister", description = "Die Finsterwaldgeister von Shan'ze Dao werden jetzt von den Mogu beherrscht.\n\nDiese einst gerissenen Schwindler dienen mittlerweile zur Gänze den Shan'ze. Sie werden von Tag zu Tag unverschämter, rauben und töten, um ihre Meister zufriedenzustellen.\n\nSie müssen eliminiert werden, seid aber vorsichtig. Sie mögen vielleicht harmlos aussehen, sind jedoch ziemlich brutal.", sourceObjective = "Tötet 30 Dunkelholzpixies oder Dunkelholzirrlichter.", progress = "Die Waldgeister müssen die Befehle ihrer Herren ausführen.", completion = "Gute Arbeit, {class}. Wenn wir nicht eingegriffen hätten, würden die Waldgeister unserer gesamten Armee bald zahlenmäßig überlegen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[31041] = { id = 31041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eiersuche!", description = "Eier. Ja, Ihr habt mich richtig verstanden. Ich habe Eier gesagt, doch zum Essen sind sie nicht.\n\nHabt Ihr schon einmal ein Wolkenschlangenei gesehen?\n\nDiese seltenen Eier sehen wie Edelsteine aus und waren einst ihr Gewicht in Gold wert.\n\nAuf Shan'ze Dao im Norden wimmelt es für gewöhnlich nur so vor Wolkenschlangen, aber die Mogu und Geister haben es auf ihre Eier abgesehen.\n\nWir müssen so viele dieser kostbaren Eier retten wie möglich.\n\nIch zähle auf EUCH, {name}.", sourceObjective = "Sammelt 8 Eier eines Wolkenreiters.", progress = "Konntet Ihr ein paar Eier finden? Die Schlangen legen ihre Eier in Nestern am Strand, aber die Waldgeister sind dafür berüchtigt, dass sie sie bei jeder Gelegenheit stehlen.", completion = "Sachte, sachte!\n\nDanke, dass Ihr diese Eier sicher geborgen habt, {name}.\n\nIch kenne da ein paar Schlangenreiter im Jadewald, die sich bestens um sie kümmern werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[31042] = { id = 31042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herzen aus Onyx", description = "Die Schlangenbinder der Shan'ze beherrschen die Gedanken der wilden Wolkenschlangen, sie erschaffen aber auch ihre eigenen finsteren Kreaturen aus Stein, Metall, Blut und uralten Zaubern.\n\nIhre Schöpfungen, die Onyxsturmklauen, bewachen die Insel im Nordwesten.\n\nIch möchte die Magie untersuchen, die diese Kreaturen bindet. Bringt mir ihre Herzen, damit ich besser verstehen kann, mit welcher Form der Zauberei wir es zu tun haben.", sourceObjective = "Sammelt 4 Herzen aus Onyx.", progress = "Die Onyxsturmklauen würden die Befehle ihrer Meister niemals missachten.", completion = "Die sind genau richtig, {name}. Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[31043] = { id = 31043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Künste", description = "Es heißt, das Shan'ze Dao einst Standort eines großen Mogutempels war.\n\nDort studierten und praktizierten die Shan'ze die Kunst, sich die Toten oder leblose Objekte untertan zu machen.\n\nEin Großteil ihres Wissens liegt noch immer unter den Ruinen der Insel im Nordwesten verschüttet.\n\nWir müssen uns ihres Wissens bemächtigen - zum einen, damit sie es nicht in die Finger bekommen, aber auch, damit wir die Natur ihrer Experimente besser verstehen.", sourceObjective = "Sammelt 8 Tafeln der Shan'ze.", progress = "Wissen ist Macht. Und genau das macht die Mogu so gefährlich.", completion = "Gut gemacht, {name}.\n\nWir werden uns umgehend daran machen, die Schrift dieser Tafeln zu dechiffrieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[31044] = { id = 31044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bronzeklauen", description = "Unter den wildesten und getreuesten der Schöpfungen der Shan'ze sind ihre Qilen.\n\nDiese Monster jagen ihre Beute, bis sie erlegt ist oder sie selbst dabei sterben.\n\nIch möchte, dass Ihr ihre Reihen ausdünnt und außerdem ihre Bronzeklauen an Euch nehmt.\n\nIhre Klauen sind stark und rasiermesserscharf - ideal, um daraus Waffen und Haken für unsere Zwecke zu schaffen.", sourceObjective = "Sammelt 20 Bronzeklauen.", progress = "Die Qilen sind wild, doch auch in Euren Augen erkenne ich das Wilde.", completion = "Diese Klauen werden sich als nützlich erweisen.\n\nGute Arbeit, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31045] = { id = 31045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illusionen der Vergangenheit", description = "{class}, ich bin auf Eure Stärke angewiesen, um die Illusionisten der Shan'ze auf Shan'ze Dao im Nordwesten zu eliminieren.\n\nIch bedaure, Euch mit dieser schwierigen Aufgabe betrauen zu müssen.\n\nDie Illusionisten zählen zu den Stärksten unter den Elitezauberern der Shan'ze.\n\nSie werden nicht leicht zu besiegen sein, aber ich kenne niemanden, <der/die> besser für diese Aufgabe geeignet ist als Ihr, {class}.", sourceObjective = "Tötet 3 Illusionisten der Shan'ze.", completion = "Ich wusste, Ihr würdet es schaffen, {name}!\n\nJetzt, wo wir es nicht mehr mit so vielen Illusionisten der Shan'ze zu tun haben, wird unsere Aufgabe hier um Einiges leichter sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[31046] = { id = 31046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleine Jungtiere", description = "Ich habe die grausamen Experimente gesehen, die die Shan'ze auf ihrer Insel im Nordwesten durchführen.\n\nDie Shan'ze brüten Schlangenjunge aus ihren Eiern aus und halten sie in winzigen, total verdreckten Käfigen.\n\nDie grausamsten Wärter hungern sie aus und quälen sie.\n\nWir müssen möglichst viele Jungtiere retten. Ich erteile Euch freie Hand, jeden Mogu, der sich Euch in den Weg stellt, zu bestrafen!", sourceObjective = "Befreit 20 Wolkenreiterjungtiere.", completion = "Diese Kreaturen werden sich an Euch als ihren Retter erinnern.\n\nDas habt Ihr gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31047] = { id = 31047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Freiheit geboren", description = "Kennt Ihr die Geschichte der großen Wolkenschlangen von Pandaria, {name}?\n\nEines Tages müsst Ihr sie Euch anhören. Doch jetzt ist keine Zeit, sie zu erzählen.\n\nIhr müsst wissen, die wilden Wolkenreiterschlangen von Tonlong stecken in der Klemme.\n\nDie Mogu fangen wilde Schlangen und verderben ihre Gedanken, um sie ihrem finsteren Willen zu beugen.\n\nGeht nach Shan'ze Dao im Nordwesten. Befreit die ausgewachsenen Schlangen aus ihren Ketten. Rettet sie!", sourceObjective = "Befreit 6 wilde Wolkenreiter von ihren Ketten.", completion = "Gute Arbeit, {race}. Es freut mich zu sehen, dass die wilden Schlangen wieder frei sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[31048] = { id = 31048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geistreiche Urnen", description = "Wir haben antike Begräbnisurnen der Mogu in den Ruinen auf Shan'ze Dao gefunden.\n\nDas mag sonst kein Problem sein, aber diese Urnen beherbergen zornige Mogugeister.\n\nSie stellen nicht nur eine Gefahr für jene Unglückseligen dar, die auf sie stoßen; in den falschen Händen könnten sie sogar zum Werkzeug der Zerstörung werden.\n\nWir müssen Shan'ze Dao von ihnen befreien.", sourceObjective = "Tötet 24 Ahnen der Shan'ze. Ahnen der Shan'ze sind in den Begräbnisurnen der Mogu zu finden.", progress = "Haben die Geister Euch Ärger gemacht?", completion = "Gut, dass wir sie los sind! Diese Mogugeister waren längst fällig.", sourceObjectiveStatus = "unverified-source-field" }
quests[31049] = { id = 31049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie gehen uns auf den Geist", description = "Die Geister von Shan'ze Dao sind von jeher launenhafte Trickster gewesen, doch jetzt sind sie unter den Einfluss der Mogu geraten.\n\nBereits jetzt organisieren sie sich unter einem neuen Anführer.\n\nDas dürfen wir nicht zulassen.\n\nIhre frechen Streiche waren eine Sache, aber wenn sie sich zusammenzuschließen, droht ihre dunkle Magie potenter und gefährlicher zu werden, als wir uns vorzustellen vermögen.\n\nSchaltet ihren Anführer aus, bevor es zu spät ist.", sourceObjective = "Tötet die Dunkelholzfee.", completion = "Gute Arbeit, {name}.\n\nDie Waldgeister mögen harmlos aussehen, aber genau das macht sie so gefährlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[31055] = { id = 31055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Biss in den Saurokapfel", sourceObjective = "Bringt \"Der Biss in den Saurokapfel\" zu Lehrensucher Cho.\n\nBereitgestellter Gegenstand:", completion = "Ich glaube nicht, dass vor Eurer Forschung die Pandaren wussten, warum eigentlich die Saurok so feindselig sind. Wir werden dieses Wissen Eurer Sammlung hinzufügen. Wenn ich etwas darüber sagen soll, dann zeigt einfach auf das entsprechende Buch in Eurer Privatsammlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[31058] = { id = 31058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Affenbande", description = "Piraten! Unsere Küsten sind von den unausgeglichensten, ungehobelsten, ungepflegtesten und ungutsten... ähm, schlechtesten Ho-zen überfallen worden, die Pandaria jemals erlebt hat. Und, um das Ganze noch schlimmer zu machen, dienen sie auch noch dem legendären Kapitän Uuk!\n\nWir sehen sie jede Nacht, wie sie auf ihrer Insel Unga Ingu feiern und Punsch brauen.\n\nWie wäre es denn, wenn wir zur Abwechslung mal ihre Getränke klauen! Ich glaube, ich kann ihre Mixtur sogar noch verbessern.\n\nSammelt ein paar Freunde und trefft mich im Süden von Unga Ingu. Es ist Zeit für einen Brausturm!", sourceObjective = "Bezwingt Kapitän Uuk.", progress = "Diese Ho-zen haben ein paar gemeine Spielsachen dabei und manche ihrer Gebräue sind noch gemeiner.", completion = "Ein guter Schlag! Wahrhaftig ein guter Schlag! Das ist die Sorte Schlag, die zurückschlägt. Gut gemacht, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[31060] = { id = 31060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dawson test POI" }
quests[31061] = { id = 31061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmritt", description = "Shan'Bu, der Anführer der Shan'ze, hält auf dem höchsten Punkt der Insel im Nordwesten ein finsteres Ritual ab.\n\nWir glauben, dass die unterworfenen Wolkenreiter der Shan'ze den Zauber mit Energie versorgen. Wie, ist uns noch nicht bekannt.\n\nWir glauben, dass die Wolkenreiter der Shan'ze noch vor der Verderbnis, die sie verpestet, gerettet werden können.\n\nNehmt diese Bronzeklauen und benutzt sie, um auf den Rücken eines Wolkenreiters der Shan'ze zu steigen.\n\nGreift sie an. Prügelt etwas Vernunft in ihre Köpfe!", sourceObjective = "Benutzt die Bronzeklauen, um 8 Wolkenreiter der Shan'ze zu besteigen. Greift sie an, um sie von ihrer Verderbnis zu befreien.", completion = "Wir begreifen weder völlig, was die Shan'ze machen, noch wie sie die wilden Schlangen beherrschen.\n\nBan hat die Theorie, dass nichts außer körperlichen Schmerzen die Gedankenkontrolle durchbrechen kann.\n\nWenn die Schmerzen der Wolkenreiter der Shan'ze groß genug sind, lockert sich der Griff der Verderbnis und sie erinnern sich endlich daran, wer sie sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[31062] = { id = 31062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn die Toten sprechen", description = "Die Experimente der Shan'ze werden von einem mächtigen Totenbeschwörer geleitet, dem Todessprecher der Shan'ze.\n\nWenn wir ihren Unternehmungen ein Ende setzen wollen, müssen wir ihren Anführer ausschalten.", sourceObjective = "Tötet den Todessprecher der Shan'ze.", progress = "Wovon sind die Mogu besessen, solche abscheulichen Experimente durchzuführen?", completion = "Ausgezeichnete Arbeit, {name}.\n\nEtwas anderes hätte ich auch nicht erwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[31063] = { id = 31063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lao-Chen und Serevex", description = "Direkt über dem Eingang im Baum im Norden von Sik'vess kämpft Lao-Chen gegen den Anführer. Er soll den zweiten Kristall zurückbringen, den wir brauchen, um uns Zutritt zum Tunnel der Mantis zu verschaffen.\n\nBrecht zu ihm auf und gewährt ihm Eure Hilfe.", sourceObjective = "Tötet Serevex mit der Hilfe von Lao-Chen dem eisernen Bauch.", completion = "Wir haben also den zweiten Kristall. Gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[31064] = { id = 31064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nurong und Rothek", description = "Falkenmeister Nurong ist nach Sik'vess im Nordwesten vorausgegangen, um dafür zu sorgen, dass der letzte Anführer der Mantis nicht entkommt.\n\nStoßt zu ihm und helft ihm, den Mantis-Anführer zu töten. Wenn Ihr ihm dabei helft, wird Nurong den letzten Kristall zurückbringen.", sourceObjective = "Tötet Rothek mit Hilfe von Falkenmeister Nurong.", completion = "Der letzte Kristall gehört uns. Unsere letzte Auseinandersetzung steht unmittelbar bevor.", sourceObjectiveStatus = "unverified-source-field" }
quests[31065] = { id = 31065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschüttet", description = "Taoshi hat ein Handfernrohr am Rand des Passes aufgestellt, um mir das Ergebnis ihrer Aufklärungsmission zu zeigen.\n\nGeht hin und schaut es Euch an.", sourceObjective = "Schaut durch das Handfernrohr an Rensais Wachposten.", progress = "Geht und schaut.", completion = "Unsere Aufgabe liegt klar vor uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[31066] = { id = 31066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ruf aus der Finsternis", description = "Die kaiserlichen Gelege habt Ihr also überlebt. Ihr seid... widerstandsfähig.\n\nDie Klaxxi hören einen weiteren Getreuen, im Norden, inmitten der Sha-verbrannten Wurzeln von Kypari Vor.\n\nEr schreit vor Schrecken und Schmerzen. Er kann nicht gerettet werden.\n\nDie Klaxxi wollen, dass er erlöst wird. Besiegt ihn. Solltet Ihr versagen, kehrt nicht hierher zurück.", sourceObjective = "Tötet den verderbten Getreuen in Kypari Vor.", progress = "Der Befehl steht. Tötet den gefallenen Getreuen.", completion = "Was?! Wie habt Ihr...\n\nDer Todesrufer war ein gewaltiger Held. Er war wohl noch nicht vollständig erwacht.\n\nIhr habt Glück gehabt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31067] = { id = 31067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Krieg den Himmel ganz erfüllt", description = "Die Mantis machen mir die Arbeit nie einfach, doch diesmal sind sie zu weit gegangen.\n\nDie gelegentlichen Angriffe aus Kor'vess können wir abwehren, doch jetzt... jetzt beginnen sie, uns einzukesseln.\n\nUnd was noch schlimmer ist: Sie saugen den Bern aus unserem Baum.\n\nDas werden wir nicht zulassen! Wir brauchen den Bern! Zum Bierbrauen!\n\nSie haben einen Bau in die Südseite des Baums gegraben. Könntet Ihr Euch für mich um sie kümmern?", sourceObjective = "Tötet Azzix K'tai.", completion = "Wir sind nicht hier, um jemanden zu verletzen. Wir wollen nur etwas Bier mit diesem Baumsaft brauen. Ist das zu viel verlangt?", sourceObjectiveStatus = "unverified-source-field" }
quests[31068] = { id = 31068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heiliges Rezept", description = "\"Wir müssen, wenn der Schrecken naht\nUnd Krieg den Himmel ganz erfüllt\nBefreien das Gefäß des Heils\nDas schläft, in seinen Kern gehüllt.\"\n\nDie Schriftrolle enthält noch weitere Strophen. Vielleicht kann jemand im Abendlichtbraugarten diese kryptische Botschaft entziffern.", sourceObjective = "Bringt die Rolle der Vorzeichen zu Lya von den Zehn Gesängen im Abendlichtbraugarten.", progress = "Ist das eine Art Schriftrolle?\n\nDürfte ich sie mir wohl anschauen?", completion = "<Lya liest die komplette Mitteilung.>\n\nDiese Schriftrolle, diese... diese Prophezeiung...\n\nSie ist entsetzlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[31069] = { id = 31069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Schatten gebunden", description = "Diese Schriftrolle, die Ihr gefunden habt...\n\nIch sehe mir immer wieder die Zeile in der zweiten Strophe an - \"durch Holz und Schatten gebunden\". Vor allem der \"Schatten\" fasziniert mich.\n\nIch muss zugeben, dass ich schon oft darüber nachgedacht habe, etwas von der verbliebenen Sha-Essenz hier in der Gegend zu nehmen und sie in ein Gebräu einzuarbeiten. Ich vermute, das ist genau der Schatten aus unserem Rezept.\n\nSüdöstlich von unserem Baum werdet Ihr hohe Sha-Konzentrationen finden... möglicherweise könnt Ihr aber auch welches von der hiesigen Tierwelt ernten.", sourceObjective = "Erntet 100 Schattentropfen, indem Ihr Sha und wilde Tiere in der Nähe des Abendlichtbraugartens tötet.", completion = "Wunderbar. Das wird einen exquisiten Zusatz zu unserem Bier abgeben.\n\nDie gefährlichsten Zutaten sind ziemlich oft auch die aromatischsten.", sourceObjectiveStatus = "unverified-source-field" }
quests[31070] = { id = 31070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dolche der Großen", description = "In diesem Rezept steht: \"scharfe Dolche der großen Wesen\"...\n\n<Olon denkt über die Zeile nach.>\n\nMushan! Das ist es!\n\nDort draußen streifen viele Mushan umher, die große, lange Zähne haben... so lang wie Dolche. Das muss die Zutat für das Rezept sein.", sourceObjective = "Besorgt 3 große Mushanzähne.", progress = "Ich frage mich, wie wir diese Reißzähne in das Bier mischen? Ich kann sie nicht zerstoßen - das wäre zu grob.\n\nVielleicht sollte ich sie einfach kurz einweichen.", completion = "Mit Mushanzähnen zu brauen ist mir noch nie vorher eingefallen.\n\nDiese Schriftrolle enthält ein paar abgefahrene Ideen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31071] = { id = 31071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schande über mich", description = "Ich habe meine Brauerfreunde im Stich gelassen.\n\nIch habe ein paar Vorräte zu der Lichtung östlich von unserem Baum gebracht... und sie dort gelassen. Mit dem Sha, das das Land verderbt, und den herumstreifenden Mantis ist es zu gefährlich, sie zurückzuholen.\n\nWenn Ihr mir bei der Suche danach helfen könntet, würde das vielleicht etwas von meiner verlorenen Ehre wiederherstellen.", sourceObjective = "Findet das verlorene Fässchen, die verlorenen Krüge und die verlorenen Picknickutensilien.", progress = "Habt Ihr sie gefunden? Ist es möglich?", completion = "Ihr habt mir Freude bereitet, Reisender.", sourceObjectiveStatus = "unverified-source-field" }
quests[31072] = { id = 31072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scharfe Dolche", description = "Vergesst sie und vergesst ihr GEBRÄU. Wir haben richtige Arbeit zu erledigen.\n\nDie Schriftolle erwähnt \"scharfe Dolche der großen Wesen\". Ich glaube, ich weiß, wo die zu finden sind.\n\nZwei Mantisleutnants patrouillieren die Mark des Schreckens im Süden. Beide tragen zeremonielle Dolche bei sich.\n\nBringt diese Dolche hierher, {name}. Wir stehen vielleicht knapp vor einer großen Sache.", sourceObjective = "Besorgt Kz'Kziks und Ilikkax' Klingen.", progress = "Ich glaube, langsam fange ich an, die nächsten paar Zeilen dieser Prophezeiung zu verstehen, {name}.\n\nHabt Ihr die Dolche schon?", completion = "Seht Euch diese Dolche an!\n\n<Lya hält die Klingen Heft an Heft.>\n\nSie wurden als Paar gefertigt! Aber wie fügt man sie zusammen...?", sourceObjectiveStatus = "unverified-source-field" }
quests[31073] = { id = 31073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch Holz gebunden", description = "<Vu sieht sich das Rezept an.>\n\nHmm... \"durch Holz gebunden\". Normalerweise brauen wir nicht mit Holz. Saft, ja... aber kein Holz.\n\nIn Ausnahmefällen fügen wir unserem Bier Kernholz von den Treants westlich von hier hinzu. Die meisten von ihnen sind den Mantis zum Opfer gefallen... doch ihre Überreste sollten für unser Rezept ausreichen.", sourceObjective = "Besorgt 8 Stücke duftendes Kernholz.", progress = "Wir brauen hier nicht mit Holz. Das verleiht dem Bier einen herben, schalen Geschmack, so ähnlich wie Wein.\n\n<Vu spuckt aus.>", completion = "Ich werde diese Teile vorbereiten.\n\nWir haben bereits etliche dieser Zutaten gesammelt! Bald muss ich einen Topf aufsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31074] = { id = 31074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holz und Schatten", description = "\"Scharfe Dolche der großen Wesen\" werden \"durch HOLZ und SCHATTEN gebunden\". Hmm.\n\nWährend meiner Zeit hier habe ich eine Menge über die Kor'thik-Mantis gelernt. Ich weiß, dass sie in ihrer Siedlung Kor'vess Schreine unterhalten.\n\nEiner von ihnen ist die Herzwurzel des Baums, in dem sie hausen. Beim anderen handelt es sich um eine dunkle Säule, die sie mit ihrer Königin verbindet.\n\nDie beiden Schreine sind das Holz und der Schatten. Wenn ich mit meiner Prophezeiung recht habe... sollten die Dolche in ihrer Gegenwart reagieren.", sourceObjective = "Findet das Mal der Kaiserin und die Herzwurzel von Kypari Kor.", completion = "{name}, seht her! Die Dolche - sie sind aneinander gebunden, zu einer gegabelten Klinge.\n\nWir sind auf der richtigen Fährte. Ich wusste doch, dass das kein Bierrezept war.", sourceObjectiveStatus = "unverified-source-field" }
quests[31075] = { id = 31075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Könige des Sonnenuntergangs", description = "Olon hatte eine gute Idee. Er glaubt, wir sollten den Waldgeistern im Westen einen Besuch abstatten und sie fragen, ob sie welche von diesen Zutaten haben. Einige Elemente in diesem Rezept erscheinen... merkwürdig.\n\nDie Rikkitun-Waldgeister haben ein Dorf westlich von Kor'vess. Hoffentlich sehen wir uns dort, {name}.", sourceObjective = "Trefft Euch mit Saftmeister Vu in Rikkitun.", completion = "Ist schon länger her, seit ich unterwegs gebraut habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[31076] = { id = 31076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal der Sturmbräus", description = "Seid gegrüßt, {race}. Ich heiße Chen Sturmbräu.\n\nIch suche nach meiner Familie. Man hat mir gesagt, dass mehrere Sturmbräus die Mauer überquert haben, um bei der Bekämpfung der Mantis zu helfen. Ich will sie finden und mich ihnen anschließen.\n\nIst Euch jemand mit dem Namen Sturmbräu begegnet, der hier durchgekommen ist? Würde es Euch etwas ausmachen, mir beim Herumfragen zu helfen?", sourceObjective = "Fragt die Bewohner des Abendlichtbraugartens, ob sie Sturmbräus gesehen haben.", completion = "<Chen hört aufmerksam zu.>\n\nDer Dicke Dan, Han, Evie und Mama. Ich verstehe.\n\nSieht so aus, als wäre Dan hier in Sicherheit. Ich werde mich auf die Suche nach Evie, Han und Mama Sturmbräu machen.\n\nGute Reise, {name}, und folgt dem Weg des Wanderers.", sourceObjectiveStatus = "unverified-source-field" }
quests[31077] = { id = 31077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evie Sturmbräu", description = "Es war zu spät. Sie war so klein... und ich kam zu spät.\n\nSie sollte richtig bestattet werden. Eine kleine Kriegerin wie sie hat etwas Besseres verdient.", sourceObjective = "Hört Euch Chens Trauerrede im Abendlichtbraugarten an.", progress = "<Chen trauert.>", completion = "<Chen ist einen Augenblick lang ruhig.>", sourceObjectiveStatus = "unverified-source-field" }
quests[31078] = { id = 31078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Han Sturmbräu", description = "Später ist auch noch Zeit zum Trauern. Doch vorher gibt es noch mehr Sturmbräus, die gefunden werden müssen.\n\nSie sagen, Han Sturmbräu wurde zuletzt bei der Erforschung von Kor'vess gesehen. Ich vermute, dass er in den Mantisbau auf der anderen Seite unterwegs war.\n\nTrefft mich dort, {name}. Ich zweifle nicht daran, dass ich mit ein paar Mantis im Alleingang fertigwerde... mit Euch an meiner Seite würde ich mich allerdings besser fühlen.", sourceObjective = "Findet Han Sturmbräu in der Morgenkammer unter Kor'vess.", progress = "Ich glaube, ich sehe dort drüben jemanden, aber ich schaffe es nicht durch diese Bernstrahlen.", completion = "Zuerst Evie und jetzt Han.\n\nIch bin schon wieder zu spät gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31079] = { id = 31079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schrecken nimmt zu", description = "Wir sind vor den Mantis geschützt. So lautete das Abkommen, das vor vielen Jahrtausenden geschlossen wurde.\n\nEs gibt jedoch Mächte, vor denen wir nicht sicher sind. Die Kypariten im Untergrund im Westen suchen uns heim, verfolgen uns... fressen uns sogar auf. Ebenso laben sich die Nebellauerer an uns.\n\nHelft unserem Volk, <Außenseiter/Außenseiterin>. Bezwingt die Kypariten.", sourceObjective = "Tötet 7 schlurfende Nebellauerer und 2 Kypariten.", progress = "Wir hassen es, aufgefressen zu werden.", completion = "Es ist gut, jemanden von Eurer enormen Größe in unserem Dorf zu haben.\n\nIhr seid vielseitig verwendbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[31080] = { id = 31080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feurige Flügel", description = "Ich glaube, das alte Stück Papier erwähnt irgendwas über \"feurige Flügel\". Die kleinen Drachen hier in der Gegend haben Flügel. Und die sind irgendwie feurig.\n\nIhr seid schneller als ich. Versucht doch, ein paar von den Drachen zu fangen... oder zumindest ihr Pulver abzuschütteln.\n\nEs lohnt sich nicht, einen harmlosen kleinen Drachen zu töten, wenn man nichts weiter von ihm will als den Glitzerstaub von seinen Flügeln.", sourceObjective = "Stupst Rikkileaflatterlinge und fangt dann 88 Sprenkel Flatterlingsstaub.", progress = "Ich konnte keines von diesen Dingern fangen!", completion = "JAWOHL!!! FLATTERLINGSSTAUB!!!\n\n<Olon wirft das Pulver in einen Topf.>\n\nDieses Gebräu sieht... merkwürdig aus und stinkt ziemlich. Langsam fange ich an zu glauben, dass Lya vielleicht recht hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[31081] = { id = 31081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urzeitliche Geisterzauber", description = "Ich vermute, wir werden die Hilfe dieser Waldgeister benötigen.\n\nWir haben zwei verzauberte Dolche, die mit Holz und Schatten aneinander gebunden sind. Jetzt brauchen wir jemanden, der unser Artefakt mit alten \"Geisterzaubern\" belegt.\n\nZeigen wir den Waldgeistern doch, dass wir es gut meinen, bevor wir sie um einen Gefallen bitten. Ich habe gehört, wie ihr Anführer Nebellauerer erwähnt hat, die mehrere Dorfbewohner entführt haben. Wenn wir diese Nebelviecher töten... bekommen wir im Gegenzug vielleicht die \"Geisterzauber\".", sourceObjective = "Tötet Ahgunoss und Mygoness.", completion = "Gute Arbeit. Ich habe gehört, wie sich die Waldgeister über uns unterhalten.\n\nWir haben ihre Aufmerksamkeit erregt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31082] = { id = 31082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gefäß des Heils", description = "Ich weiß, wonach Ihr und das Pandamädchen sucht. Wir können den Ritus für Euch abhalten... später.\n\nVorher benötige ich aber Hilfe. Die Saat fällt von unserem großen Mutterbaum. Sie einzusammeln ist unsere Aufgabe, selbst in gefährlichen Zeiten wie diesen.\n\nBegleitet meine Sänger zur Muttersaat, damit sie sie zur Sammelgrube zurückbringen können.", sourceObjective = "Bringt mit der Hilfe der Rikkitunsänger 3 Muttersaatexemplare zur Sammelgrube in Rikkitun.\n\nWenn Ihr von Euren Sängern getrennt werdet, könnt Ihr sie mit der Glocke von Rikkitun erneut herbeirufen.", completion = "Ja, gut. Die Sache mit der Muttersaat hat sich erledigt.\n\nJetzt können wir uns über Eure Verzauberung unterhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[31083] = { id = 31083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldversprechen", description = "Sobald die Kreatur gestorben war, erschien eine seltsame Gruppe von Waldgeistern und nahm die Perle weg.\n\n Die Waldgeister leben in der Nähe, in einem Dorf namens Rikkitun. Vielleicht solltet Ihr das untersuchen.", sourceObjective = "Sprecht mit Häuptling Rikkitun in Rikkitun in der Schreckensöde.", completion = "Diese Glanzsaat... das war Eure Tat? Ich hatte bereits eine... aber zwei sind besser.\n\nWir brauchen nur die Samen, nicht die Hüllen. Wenn Ihr wollt, könnt Ihr sie behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[31084] = { id = 31084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bindung des Glanzes", description = "Es ist schon sehr, sehr lange her, seit unser Stamm gebeten wurde, dieses Ritual abzuhalten. Ich werde mein Bestes geben.", sourceObjective = "Erlaubt, dass Häuptling Rikkitun die Gegabelte Klinge verzaubert.", completion = "Die Klinge ist bereit.\n\nBleibt nur noch eine Aufgabe: Ihr müsst sie benutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31085] = { id = 31085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer und Ängste", description = "Wir haben die Klingen gefunden, mit Holz und Schatten gebunden und mit einem alten Geisterzauber gesegnet. Wenn ich mich nicht irre, ist es jetzt Zeit, dieses Ding zu benutzen.\n\nDie Waldgeister haben ein altes Saftstück in der Bernüberwinterung erwähnt, einer Höhle der Mantis nicht weit vom Palast ihrer Kaiserin. Das muss das \"uralte Blut\" aus der Prophezeiung sein.\n\nWas auch immer in diesem Saft enthalten ist, es muss wichtig sein. Viel Glück, {name}.", sourceObjective = "Benutzt die Gabel des Ruins bei Iyyokuk dem Wachen und beschützt ihn dann, bis er entkommen kann.", completion = "Im Inneren dieses Berns war ein... ein Mantis? Auf die Idee, dass die Lösung für unseren Krieg mit den Mantis... ein anderer Mantis sein könnte, wäre ich nie gekommen.\n\nEs gibt noch viel für mich zu lernen, eins weiß ich aber ganz genau: Das war BESTIMMT kein Bierrezept.", sourceObjectiveStatus = "unverified-source-field" }
quests[31086] = { id = 31086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uraltes Blut", description = "In einer Angelegenheit sind Lya und ich uns einig: Das \"uralte Blut\" ist so gut wie sicher der Saft der großen Bäume in der Gegend. Ich sollte das wissen, schließlich braue ich ständig damit.\n\nDer älteste dieser Bäume dient der Großkaiserin Shek'zeer als Zuhause - er ist unter dem Namen \"Das Herz der Angst\" bekannt. Findet mir etwas Bern von diesem Baum, dann sollte unser Gebräu komplett sein.", sourceObjective = "Besorgt einen Brocken erstarrten Berns.", progress = "Und? Glück gehabt?", completion = "Das sollte reichen! Rezept... vollständig.\n\nUnd jetzt wollen wir mal sehen, wie dieses Gebräu schmeckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31087] = { id = 31087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere Reichweite ausbauen", description = "Die Klaxxi'va hören noch einen Getreuen. Seine Schreie sind schwach und verlieren sich in der Dunkelheit.\n\nDas Signal muss verstärkt werden.\n\nEs gibt einen Turm in der Bernscheinkuhle, der schon seit vielen Jahren verstummt ist. Er muss singen, die Klaxxi verlangen es!\n\nDieses Mal begleite ich Euch. Ihr werdet mir helfen, ihn zu reparieren.\n\nNehmt den Resonanzkristall und trefft mich in der Kuhle.", sourceObjective = "Aktiviert das resonierende Signal in der Bernscheinkuhle.", completion = "Es ist gut, dass Ihr gekommen seid.\n\nVielleicht seid Ihr ja doch nicht so nutzlos, wie ich gedacht habe...", sourceObjectiveStatus = "unverified-source-field" }
quests[31088] = { id = 31088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schuld und Sühne", description = "Am Stechenden Pfad finden sich junge Kyparibäume. Die Kaiserin entzieht den Schösslingen viel zu früh ihre Energie, Fremdling. Sie müssen erst wachsen, bevor der Bern entnommen werden kann.\n\nDie Klaxxi'va verlangen, dass dieses Verbrechen bestraft wird! Es wird ihnen gefallen, wenn Ihr den Tod auf die Bernernter der Ik'thik niederregnen lasst.", sourceObjective = "Tötet 8 Bernernter der Ik'thik auf dem Stechenden Pfad.", completion = "Die Klaxxi sind zufrieden mit unserer Arbeit, Fremdling. Ihr habt Euch als nützlicher herausgestellt, als wir angenommen hatten.", sourceObjectiveStatus = "unverified-source-field" }
quests[31089] = { id = 31089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niemals wieder am Meer", description = "Die Klaxxi'va haben zu mir gesprochen, Fremdling. Der Getreue war im Salzigen Schlick verborgen, doch inzwischen hat die Tarnung versagt.\n\nDie Echsenmänner haben ihn umstellt. Er darf ihnen nicht in ihre schuppigen Hände fallen.\n\nIhr werdet ihn finden; Ihr werdet ihn erwecken. Kehrt nicht ohne ihn zurück!\n\nFür diese Tat werden uns die Klaxxi dankbar sein.", sourceObjective = "Benutzt die Stimmgabel der Klaxxi bei den meergepeitschten Felsen, um den Getreuen zu erwecken.", completion = "Was... was für eine Kreatur seid Ihr?\n\nWie habt Ihr mich aufgeweckt?", sourceObjectiveStatus = "unverified-source-field" }
quests[31090] = { id = 31090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Je älter, desto besser", description = "Es ist ein Verbrechen, die jungen Bäume abzuernten, doch den Bern zu verschwenden ist eine noch viel größere Schandtat.\n\nFrischer Bern ist nicht so wirkungsvoll, doch die Klaxxi brauchen ihn, um den Kampf fortführen zu können. Wir werden ihnen mehr davon bringen und sie werden mich mit Dank überhäufen!\n\nSammelt den frischen Bern. Wir lagern ihn ein, bis er lange genug gereift ist, um verzehrt zu werden.", sourceObjective = "Sammelt 7 mit Bern gefüllte Gläser von den Bernsammlern auf dem Stechenden Pfad.", progress = "Ich würde ja mit Euch gehen, um Bern zu sammeln, aber meine Talente finden hier besseren Einsatz.", completion = "Selbst roher Bern wird uns nützlich sein. In Zeiten wie diesen können wir es uns nicht leisten, wählerisch zu sein.\n\nDie Klaxxi'va werden sich freuen, dass ich daran gedacht habe. Ich werde ihnen sagen, dass Ihr mir geholfen habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[31091] = { id = 31091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiedervereinigt!", description = "Ihr seht mich an und stellt fest, dass ich kein großer Krieger bin. Warum wurde ich als Getreuer auserkoren? Nicht alle Waffen kann man sehen, <Erwecker/Erweckerin>. Man sollte nicht nach dem Aussehen allein urteilen.\n\nEhe ich Euch mehr erzähle, muss ich wissen, dass ich Euch vertrauen kann.\n\nZur Zeit meiner Bewahrung wurde etwas, das mir wichtig war, versteckt. Ohne es bin ich nichts.\n\nVerteidigt mich, während ich meine größte Waffe zutage fördere, und Ihr habt mein Vertrauen.", sourceObjective = "Helft Kaz'tik dem Manipulator, seine größte Waffe zutage zu fördern.", completion = "Kovok ist so imposant wie bei unserer letzten Begegnung. Er wird den Klaxxi große Siege bescheren.", sourceObjectiveStatus = "unverified-source-field" }
quests[31092] = { id = 31092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Füttern oder gefressen werden", description = "Nach vielen Jahren der Arbeit mit den Kunchong habe ich eine Theorie entwickelt: Einen von klein auf großzuziehen stärkt die Bindung und damit auch die akustische Verbindung.\n\nIch hatte gerade mit Kovoks Erziehung begonnen, als ich für die Umhüllung auserkoren wurde. Er ist noch jung und muss sorgfältig ausgebildet werden, um sein vollständiges Potenzial zu erlangen.\n\nIch vertraue Euch Kovok an, aber seid gewarnt: Sollte ihm irgendetwas zustoßen, büßt Ihr mir dafür mit dem Leben.\n\nAls Erstes müsst Ihr ihn füttern, um sein Vertrauen zu gewinnen. Die Schildkröten hier in der Gegend sollten sich dafür gut eignen.", sourceObjective = "Beginnt mit Kovoks Erziehung, indem Ihr ihn mit 6 saftigen Schildkrötenfilets von Salzpanzerschnappern aus dem Salzigen Schlick füttert.", completion = "Sehr gut! Ich hatte so halb befürchtet, dass Kovok einfach Euch fressen würde. Was für eine schöne Überraschung Euch beide heil und im Ganzen zu sehen.\n\nVielleicht liegt es Euch im Blut, Kunchong aufzuziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31093] = { id = 31093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ho-zen im Nebel", sourceObjective = "Bringt \"Ho-zen im Nebel\" zu Lehrensucher Cho im Heim des Wissens.\n\nBereitgestellter Gegenstand:", completion = "Die Ho-zen sind von Natur aus sehr ungestüm.\n\nWir werden dieses Wissen Eurer Sammlung hinzufügen. Wenn Ihr wollt, dass ich es Euch schildere, müsst Ihr einfach auf den korrekten Band in Eurer Sammlung zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31094] = { id = 31094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fischschwänke", sourceObjective = "Bringt \"Fischschwänke\" zu Lehrensucher Cho im Heim des Wissens.\n\nBereitgestellter Gegenstand:", completion = "Was für eine Freude. Die Jinyu haben mich immer schon fasziniert. So ein friedfertiges Volk, gesegnet mit so viel Weisheit.\n\nWir werden dieses Wissen Eurer Sammlung hinzufügen. Wenn ich etwas darüber sagen soll, dann zeigt einfach auf das entsprechende Buch in Eurer Privatsammlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[31095] = { id = 31095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das dunkle Herz der Mogu", sourceObjective = "Bringt \"Das dunkle Herz der Mogu\" zu Lehrensucher Cho im Heim des Wissens.\n\nBereitgestellter Gegenstand:", completion = "Mogu. Schon bei ihrem Namen steht mir der Pelz zu Berge. Wir werden dieses Wissen Eurer Sammlung hinzufügen. Wenn ich etwas darüber sagen soll, dann zeigt einfach auf das entsprechende Buch in Eurer Privatsammlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[31096] = { id = 31096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wofür es sich zu kämpfen lohnt", sourceObjective = "Bringt \"Wofür es sich zu kämpfen lohnt\" zu Lehrensucher Cho im Heim des Wissens.\n\nBereitgestellter Gegenstand:", completion = "Wer hätte gedacht, dass die Befreiung der Pandaren mit einem einzigen Schlag begann?\n\nWundervoll. Wir werden dieses Wissen Eurer Sammlung hinzufügen. Wenn ich etwas darüber sagen soll, dann zeigt einfach auf das entsprechende Buch in Eurer Privatsammlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[31097] = { id = 31097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz des Mantisschwarms", sourceObjective = "Bringt \"Das Herz des Mantisschwarms\" zu Lehrensucher Cho im Heim des Wissens.\n\nBereitgestellter Gegenstand:", completion = "Als wir unser Forschungsprojekt begannen, hätte ich nie gedacht, einmal so viel über dieses schreckliche Volk zu erfahren.\n\nWir werden dieses Wissen Eurer Sammlung hinzufügen. Wenn ich etwas darüber sagen soll, dann zeigt einfach auf das entsprechende Buch in Eurer Privatsammlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[31100] = { id = 31100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Lied der Yaungol", sourceObjective = "Bringt das \"Lied der Yaungol\" zu Lehrensucher Cho im Heim des Wissens.\n\nBereitgestellter Gegenstand:", completion = "Die Yaungol sind ein sehr widerstandsfähiges Volk, gestärkt durch ihr Exil in den Gebieten jenseits der Mauer. Wir werden dieses Wissen Eurer Sammlung hinzufügen. Wenn ich etwas darüber sagen soll, dann zeigt einfach auf das entsprechende Buch in Eurer Privatsammlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[31102] = { id = 31102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die sieben Bürden des Shaohao", sourceObjective = "Bringt \"Die sieben Bürden des Shaohao\" zu Lehrensucher Cho im Heim des Wissens.\n\nBereitgestellter Gegenstand:", completion = "Diese Geschichte habe ich schon lange versucht aufzuklären. Seit das Sha freigelassen wurde, hatte ich das Gefühl, dass diese Geschichte die Grundlage für alles ist.\n\nWir werden dieses Wissen Eurer Sammlung hinzufügen. Wenn ich etwas darüber sagen soll, dann zeigt einfach auf das entsprechende Buch in Eurer Privatsammlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[31103] = { id = 31103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ballade von Liu Lang", sourceObjective = "Bringt die \"Ballade von Liu Lang\" zu Lehrensucher Cho im Heim des Wissens.\n\nBereitgestellter Gegenstand:", completion = "Die lange verloren geglaubte Geschichte von Lou Lang und seiner Wandernden Insel. Eine hervorragender Neuzugang für Eure Sammlung. Wenn ich etwas darüber sagen soll, dann zeigt einfach auf das entsprechende Buch in Eurer Privatsammlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[31104] = { id = 31104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Herausforderers: Yalia Weisenwisper", description = "Die Brüder und Schwestern bei den Shado-Pan flüstern noch immer hinter vorgehaltener Hand über Eure Heldentaten, {name}.\n\nYalia hat sogar selbst Interesse an Euren Studien bekundet.\n\nSie wünscht, Euch im Ausbildungsring herauszufordern.\n\nIhr solltet sie nach Möglichkeit beeindrucken. Wenn Euch das gelingt, kann es durchaus sein, dass sie Euch in Zukunft helfen wird.", sourceObjective = "Fordert Yalia Weisenwisper heraus und bezwingt sie im Ring des Herausforderers.", completion = "Ihr habt es geschafft! Ihr habt Yalia geschlagen!\n\nIhr habt ganz eindeutig ihre Gunst gewonnen, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31105] = { id = 31105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mogubedrohung", description = "Unsere Späher haben Truppen der Mogu auf Shan'ze Dao im Nordwesten entdeckt.\n\nDie Insel ist angeblich unbewohnt, deshalb ist ihre Anwesenheit dort beunruhigend.\n\nNoch beunruhigender ist die Tatsache, dass sie unheimliche Experimente auf der Insel durchführen.\n\nIch brauche jemand Tüchtiges wie Euch, {class}, um die Lage zu prüfen.\n\nDie Shan'ze werden Euch vermutlich Probleme bereiten. Wenn dieser Fall eintritt, tötet sie.", sourceObjective = "Tötet 12 Schlangenbinder oder Bestienmeister der Shan'ze.", completion = "Die Shan'ze führen etwas im Schilde. Gut gemacht, {name}, wir müssen aber weiter im Auge behalten, was sie machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31106] = { id = 31106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mogubedrohung", description = "Unsere Späher haben Truppen der Mogu auf Shan'ze Dao im Nordwesten entdeckt.\n\nDie Insel ist angeblich unbewohnt, deshalb ist ihre Anwesenheit dort beunruhigend.\n\nNoch beunruhigender ist die Tatsache, dass sie unheimliche Experimente auf der Insel durchführen.\n\nIch brauche jemand Tüchtiges wie Euch, {class}, um die Lage zu prüfen.\n\nDie Shan'ze werden Euch vermutlich Probleme bereiten. Wenn dieser Fall eintritt, tötet sie.", sourceObjective = "Tötet 12 Schlangenbinder oder Bestienmeister der Shan'ze.", progress = "Wie viele waren es?", completion = "Die Shan'ze führen etwas im Schilde. Gut gemacht, {name}, wir müssen aber weiter im Auge behalten, was sie machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31107] = { id = 31107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bürger eines neuen Reichs", description = "Auf Shek'zeers Befehl wurde der große Kyparibaum von Kypari Vor zu einem Totem des Schreckens verzerrt.\n\nGenau wie die vor dem Palast, wird auch das Gelege in der Nähe jetzt dazu verwendet, unsere Schwarmgeborenen zu verderben.\n\nBergt die Eier der Vor'thik, bevor sie verderbt werden. Wir werden sie hier ausbrüten. Sie werden die Bewohner eines neuen Reiches sein, frei vom Sha.", sourceObjective = "Sammelt 10 Eier der Vor'thik in Kypari Vor.", progress = "Kypari Vor war früher einmal schön. Reich an Bern und umgeben von erstklassigen Jagdrevieren.", completion = "Sie sind so groß. Sie werden bald ausschlüpfen.\n\nGut. Wir werden sie vielleicht brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31108] = { id = 31108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konzentrierte Furcht", description = "Bern ist Macht. Er bringt Leben.\n\nDieser... Schreckensbern, den Ihr mir gebracht habt, ist verderbt. Er ist konzentrierte Angst.\n\nDie Vor'thik wissen das sehr wohl. Ihr Kypari wurde vollständig vom Sha umhüllt und sie benutzen den Schreckensbern, um ihre eigenen Schwarmgeborenen zu beleben.\n\nBringt mir die Kristalle, die von den Angstformern der Vor'thik in ihren Ritualen verwendet werden. Die Klaxxi werden sie untersuchen und über die Art ihrer Entsorgung entscheiden.", sourceObjective = "Sammelt 4 Schreckensbernfokusse von den Angstformern der Vor'thik in Kypari Vor.", progress = "Habt Ihr die Kristalle?", completion = "Ich frage mich, was wohl passieren würde, wenn Ihr einen davon essen würdet? Was würde er mit Eurem weichen, rosaroten Inneren anstellen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31109] = { id = 31109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vernichtung des Schwarms", description = "Die Kaiserin sammelt weiter ihre Truppen. Wenn wir nicht eingreifen, werden sie die Mauer stürmen - selbst, wenn das bedeutet, sie unter den Leichen einer Million Schwarmgeborener zu begraben.\n\nLasst uns einen besseren Ort für diese Leichen finden.\n\nSagt Bescheid, wenn Ihr Euch zu den Gelegen aufmachen wollt - gerne werde ich Euch dort absetzen.", sourceObjective = "Tötet 40 Mantis der Shek'zeer in den Gelegen von Shek'zeer. Bittet Kil'ruk den Windschnitter, Euch dort abzusetzen.", completion = "Das sollte vorläufig genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31110] = { id = 31110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch das Portal", description = "Ach, genau <der/die:c> {class}, <den/die:c> ich sehen wollte!\n\nEndlich haben wir herausgefunden, warum das Portal nicht funktioniert. Wir brauchen mehr arkanes Pulver!\n\nEine Lieferung hierher zu senden, würde Monate dauern, doch zum Glück tragen die Mogu auf dieser Insel jede Menge für ihre eigenen Zauber bei sich.\n\nSie verwenden normalerweise etwas älteres Material, also werden wir viel davon brauchen.", sourceObjective = "Sammelt 1000 Einheiten uraltes arkanes Pulver.", progress = "Habt Ihr das Pulver gefunden?", completion = "Ausgezeichnet! Hervorragend!\n\nDas ist genau das richtige Zeug, {name}.\n\nWir machen uns gleich an die Arbeit. Ich habe keinerlei Zweifel daran, dass wir bald soweit sein werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[31111] = { id = 31111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zan'thik auslöschen", description = "Die Krieger von Zan'vess gehören zu den am meisten gefürchteten und respektierten im ganzen Reich und das aus gutem Grund.\n\nPfähler sind unübertroffen in ihrer Meisterschaft des Speeres - zweifellos hat Malik zu seiner Zeit mit den Zan'thik trainiert. Ihre Manipulatoren befehlen über schreckliche Schallkräfte mit der Leichtigkeit und der Zartheit eines Atemzugs.\n\nSie beide müssen erledigt werden.", sourceObjective = "Tötet 6 Pfähler der Zan'thik und 6 Manipulatoren der Zan'thik in Zan'vess.", completion = "Ich gebe zu, Erwecker, ich bin beeindruckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31112] = { id = 31112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie sind so dornig!", description = "Einst war diese Kiste voller Vorräte, doch sie wurde vollständig geplündert.\n\nEine kurze Überprüfung des Gebiets offenbart Spuren der Diebe. Eisige Dornen, genau wie die der Wassergeister an der Küste im Osten.\n\nFür Eure Gruppe Überlebender ist dies eine Situation auf Leben und Tod. Die Vorräte müssen von den diebischen Plagen geborgen und zurück ins Lager gebracht werden.", sourceObjective = "Sammelt 5 Notvorräte von den Wassergeistern.", progress = "Habt Ihr die Vorräte zurückerlangen können, Kumpel?", completion = "Sieh mal einer an!\n\nDiese Vorräte sollten unser Überleben für ein paar Tage mehr sichern.\n\nIhr habt's geschafft, sie nicht in die Luft zu jagen. Sehr gut, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[31113] = { id = 31113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Streitlager Gai-Cho angreifen", description = "Die Yaungol sind immer ein Ärgernis, aber die Gruppe aus dem Streitlager Gai-Cho im Nordosten hat sich unlängst für einen Übergriff auf den Kun-Lai mit den Yaungol von Osul verschworen.\n\nEin solcher Übergriff darf nicht ungestraft bleiben.\n\nGeht hin und greift das Streitlager Gai-Cho an. Wir müssen sicherstellen, dass sie beschäftig sind, damit sie sich nicht neu formieren können, um das Ochsentor noch einmal anzugreifen.", sourceObjective = "Tötet 16 Yaungol, Erdsprecher oder Pechschleuderer von Gai-Cho.", completion = "Nun - das sollte sie eine Zeit lang vor weiteren Angriffen abschrecken. Gute Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31114] = { id = 31114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf das Plateau des Totensprechers", description = "Wir haben die Totensprecher immer in Ruhe gelassen. So lange waren sie lediglich dafür verantwortlich, die geheiligten Grabstätten der Yaungolstämme zu pflegen.\n\nJetzt jedoch haben sie sich der dunklen Magie verschrieben und schänden die Gebeine ihrer einstigen Klanbrüder... \n\nIch weiß weder, wo sie diese dunkle Magie erlernt haben noch warum sie ihren Toten auf einmal den Respekt verweigern – und es fehlt uns die Zeit, es herauszufinden. \n\nWir müssen sie aufhalten.", sourceObjective = "Tötet 8 Leichenschänder des Totensprechers und 1 Zermalmer des Totensprechers.", progress = "Habt Ihr die Totensprecher besiegt?", completion = "Weil sich die Totensprecher in der Verwendung dieser dunklen Magie verschworen haben, haben sie ihr Recht auf Protektion verwirkt. Ich hoffe, dass Eure Taten sie von ihrem eingeschlagenen Pfad abbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31116] = { id = 31116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisterstaub", description = "Die Geister, die die Yaungol von den sterblichen Überresten ihrer Vorfahren einfangen, enthalten immer noch etwas von ihrer Lebensessenz.\n\nWenn Ihr die Geister im Kampf besiegt, könnt Ihr diese Essenz in Form von Staub einsammeln und dann zu ihren Leichen zurückbringen, was sie endlich ins nächste Leben entsenden wird.\n\nNur so können die Taten der Totensprecher wiedergutgemacht werden. Außerdem ist es gut für unsere Sicherheit.", sourceObjective = "Bringt 8 Geister zur ihren sterblichen Überresten auf dem Plateau des Totensprechers zurück.", progress = "Wurden die Geister zur letzten Ruhe gebettet?", completion = "Sehr gut, Ihr habt bei der Wiedergutmachung dieses schrecklichen Fehlers geholfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31117] = { id = 31117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uruk!", description = "Uruk ist der Totensprecher der Yaungol von Tonlong. Eure Mission ist erst dann komplett abgeschlossen, wenn Ihr ihn besiegt habt. Legt los!", sourceObjective = "Tötet Uruk auf dem Plateau des Totensprechers in der Tonlongsteppe.", completion = "Uruk ist tot! Diese Bedrohung sind wir los, zumindest für heute. Vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31118] = { id = 31118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schrift der Totensprecher", description = "Wir müssen herausfinden, was mit den Totensprechern passiert ist.\n\nSchon seit so vielen Jahren bestand ihre Aufgabe lediglich darin, die Grabstätten zu pflegen und für die Begräbnisse der gefallenen Soldaten zu sorgen.\n\nDoch bei einem kürzlich stattgefundenen Schlachtzug haben wir eine Schrifttafel entdeckt, die in einer Art und Weise verschlüsselt ist, wie wir es noch nie zuvor gesehen haben. Wenn Ihr eine verschlüsselte Schriftrolle von einem der Totensprecher besorgt, können wir beginnen, den Schlüssel zusammenzusetzen und nachzuvollziehen, was geschehen ist.", sourceObjective = "Nehmt den Yaungol auf dem Plateau des Totensprechers eine Schriftrolle der Blutbindungsriten ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[31119] = { id = 31119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feind meines Feindes... ist immer noch mein Feind!", description = "Die Mantis sind unsere Feinde. Genau wie die Yaungol von Gai-Cho.\n\nEin Glück, dass die beiden auch miteinander verfeindet sind. Mantis aus Kri'vess greifen ständig Gai-Cho-Yaungol an, die diese wiederum an ihren Vordertoren aufhalten.\n\nIch möchte, dass Ihr Chaos stiftet. \"Borgt\" Euch in Gai-Cho ein paar hochexplosive Ölfässer und werft sie aus der Luft auf das Schlachtfeld.\n\nMir ist egal, wen Ihr umbringt, solange Ihr dafür sorgt, dass es viele sind.", sourceObjective = "Benutzt hochexplosive Fässer voll Yaungolöl, um damit 100 Mantis oder Yaungol auf dem Schlachtfeld von Gai-Cho zu töten.", completion = "Ha! Gute Arbeit. Das wird beide lehren, sich mit den Shado-Pan anzulegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31120] = { id = 31120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cheng Bo!", description = "Cheng Bo ist der Kriegshetzer des Streitlagers Gai-Cho. Einen Dämpfer habt Ihr ihrem Betrieb bereits verpasst - jetzt habt Ihr Gelegenheit, ihnen einen wirklich heftigen Schlag zu versetzen. \n\nTötet den Kriegshetzer!", sourceObjective = "Tötet Cheng Bo im Streitlager Gai-Cho in der Tonlongsteppe.", progress = "Wie läuft der Angriff?", completion = "Jetzt, da Cheng Bo überwältigt ist, können wir unsere Anstrengungen wieder voll auf unsere anderen Feinde konzentrieren. Eure Leistungen verdienen Respekt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31121] = { id = 31121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bleibt ein Weilchen und hört zu", description = "Schnell, schnell, schnell - ist Euer Volk immer so in Eile?\n\nSetzt Euch und trinkt einen Tee mit mir, dann können wir Euer Problem besprechen.\n\n<Lehrensucher Chos Lippen verziehen sich zu einem geduldigen Lächeln.>", sourceObjective = "Trinkt aus Chos Teekanne.", progress = "Ich hoffe, ich habe Euch nicht gelangweilt, Reisender.", completion = "Ich werde Euch helfen, Reisender, aber zunächst erzählt mir etwas über diese Horde...", sourceObjectiveStatus = "unverified-source-field" }
quests[31127] = { id = 31127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Herausforderers: Chao die Stimme", sourceObjective = "Fordert Chao die Stimme heraus und besiegt sie anschließend im Kampf in der Shado-Pan-Garnison in der Tonlongsteppe.", completion = "Ich bin mir sicher, dass sie Euch das nicht übel nimmt. Sie hat einfach eine Schwäche für gute Kämpfe.\n\nIhr solltet Euch mit Ihr unterhalten, wenn ich das nächste Mal ein paar Missionen für Euch habe. Wie Ihr bestimmt erkannt habt, ist sie ist eine ziemlich fähige Kämpferin.", sourceObjectiveStatus = "unverified-source-field" }
quests[31128] = { id = 31128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Herausforderers: Lao-Chen der eiserne Bauch", description = "Lao-Chen scheint völlig abgehoben zu sein... oder vielmehr in seinem Bier versunken.\n\nSeit seinen letzten Kämpfen scheint er völlig davon besessen zu sein, das perfekte Gebräu für den Kampf zu entwickeln.\n\nDas ist ja alles gut und schön, wir brauchen ihn aber als Kämpfer!\n\nIhr solltet ihn zum Kampf herausfordern, vielleicht könnt Ihr ihn damit aufrütteln. \n\nWenn Ihr ihn besiegt, will er vermutlich losziehen und sich am Kampf beteiligen, nur um Euch zu übertreffen!", sourceObjective = "Fordert Lao-Chen den eisernen Bauch heraus und besiegt ihn anschließend im Kampf in der Shado-Pan-Garnison in der Tonlongsteppe.", completion = "Wow, Ihr müsst Lao-Chen beeindruckt haben. Er redet von nichts anderem als davon, wie er sich darauf freut, aufzubrechen und mit Euch zu kämpfen. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[31129] = { id = 31129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal der Sturmbräus", sourceObjective = "Fragt die Bewohner des Abendlichtbraugartens, ob sie Sturmbräus gesehen haben.", completion = "<Chen hört aufmerksam zu.>\n\nDer Dicke Dan, Han, Evie und Mama. Ich verstehe.\n\nSieht so aus, als wäre Dan hier in Sicherheit. Ich werde mich auf die Suche nach Evie, Han und Mama Sturmbräu machen.\n\nMacht's gut, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31130] = { id = 31130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Besuch bei Lehrensucher Cho", description = "<Fremder/Fremde>, ich kann Euch vielleicht helfen, Euren Prinz zu finden. Aber erst wüsste ich gern noch ein wenig mehr über Euch und Euer Volk.\n\nHelft mir mit meinen Aufgaben und wir können ein wenig reden.\n\nIhr seht vielleicht aus wie <ein Kriegsveteran/eine Kriegsveteranin>, aber Ihr habt doch bestimmt ein paar Minuten übrig, um einem Bücherwurm wie mir bei der Hausarbeit zu helfen, oder?", sourceObjective = "Freundet Euch mit Lehrensucher Cho an, indem Ihr ihm Aufgaben abnehmt: Stutzt seinen Baum, streicht seine Mauer und füttert seine Vögel.", progress = "Es geht doch nichts über ein wenig Handarbeit, um aus Fremden Freunde zu machen, denkt Ihr nicht auch?", completion = "Trotz all Eurer Jahre des Kampfes habt Ihr noch immer ein Auge fürs Schöne, {name}. Das gefällt mir!\n\nJetzt lasst uns Euren verschwundenen Prinzen finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[31131] = { id = 31131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weißblütensee", description = "Laut der Berichte ist heute alles ruhig am Weißblütensee. Aber ich habe trotzdem Ren Feuerzunge und Hee Samtfuß dorthin geschickt, damit es so bleibt.\n\nWenn Ihr weiter helfen möchtet, dann begebt Euch auf die Westseite des Sees und trefft Euch mit Hee. Helft ihm dabei, die Gegend zu sichern und vor allen Bedrohungen zu schützen.", sourceObjective = "Sprecht mit Hee Samtfuß am Weißblütensee.", completion = "<Hee Samtfuß lächelt, als Ihr Euch ihm nähert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[31132] = { id = 31132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In meine Situation versetzen", description = "Oh, was ist nur mit meinen Manieren? Ich bin ja hier der Gastgeber.\n\nErlaubt mir, Euch ein wenig über mich selbst und mein Volk zu berichten, bevor ich Euch Fragen stelle.", sourceObjective = "Sprecht mit Lehrensucher Cho am Ring der Knochen.", completion = "Die beste Art, Euch zu erklären, was es mit einem Lehrensucher auf sich hat, ist wahrscheinlich, es Euch zu zeigen...", sourceObjectiveStatus = "unverified-source-field" }
quests[31133] = { id = 31133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aggressive Kor'thik", description = "Ich bin kein Brauer - der schiere Anblick dieser Zutatenberge macht mich schwindelig. Stellt das Bier einfach vor mich hin, wenn es fertig ist.\n\nNein, ich bin hier, um dafür zu sorgen, dass die Brauer nicht in Stücke geschnitten werden, während sie versuchen, das perfekte Bier zu brauen. Das ist keine einfache Aufgabe.\n\nDie Kor'thik-Mantis auf der anderen Seite dieses Beckens greifen uns Nacht für Nacht an. Falls Ihr ohnehin in diese Richtung geht, warum revanchiert Ihr Euch nicht und attackiert ein paar von ihnen?", sourceObjective = "Tötet 17 Kor'thik-Mantis in Kor'vess.", completion = "Ihr würdet eine gute Biergartenwache abgeben, {race}. Meldet Euch bei mir, falls Euch diese ganze \"{class}\"-Geschichte jemals zum Hals raushängen sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[31134] = { id = 31134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn diese Steine sprechen könnten", description = "Dies ist ein sehr, sehr alter Ort, <Reisender/Reisende>.\n\nErst vor kurzem habe ich eine Methode entwickeln können, mit der die vergessene Sprache, die in diese Steine gemeißelt wurde, übersetzt werden kann.\n\nOh, Entdeckungen sind immer so aufregend! Glaubt mir, ich kriege nie genug davon.\n\nIhr seid der Gast, bitte, erweist mir die Ehre und tretet vor. Ich bestehe darauf.\n\nNutzt diesen Schlüssel, um den Steinen ihre Geheimnisse zu entlocken.", sourceObjective = "Nutzt die Steinmonolithen am Ring der Knochen.", progress = "Eure Hilfe ist mir sehr willkommen, Reisender.", completion = "Ich glaube, wir haben für einen Tag genug übersetzt.\n\nDie Erfahrung war hoffentlich aufschlussreich für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[31135] = { id = 31135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zukunft von Gnomeregan", description = "Jeder Überlebende, den wir aus den vergifteten Hallen von Gnomeregan befreien können, ist wie ein Sieg für uns. Kämpfer wie Ihr werden eine wichtige Rolle bei der Zukunft von Gnomeregan spielen, {class}. Aus diesem Grund hat unser Herrscher, Hochtüftler Mekkadrill, ein Team von Lehrern zusammengestellt, die Euch helfen werden, Eure Künste zu erlernen.\n\nXi, Freundin der Winzlinge, kommt aus einem weit entfernten Land zu uns und Euch ausbilden und Euch helfen, Euch an ein Leben an der Oberfläche zu gewöhnen. Sie erwartet Euch auf dem kleinen Übungsfeld auf der anderen Straßenseite.", sourceObjective = "Trefft Euch mit Xi, Freundin der Winzlinge, in Neu-Tüftlerstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31136] = { id = 31136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter den eigenen Linien", description = "Die Späher berichten, dass ein Imperion unsere Linien im Süden durchbrochen haben soll und sich jetzt auf der Straße im östlichen Tal befindet.\n\nIch brauche jemanden, der ihn umgehend aufhalten kann. Bitte findet und tötet ihn so schnell wie möglich, {name}.", sourceObjective = "Tötet General Temuja.", completion = "Gute Arbeit. Ich hoffe, dass wir uns wieder einmal auf Euch verlassen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[31137] = { id = 31137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hochtüftler", description = "Ich weiß nicht, ob Ihr Euch an Mekkadrill erinnert. Nevin und die anderen Gnome haben mir gesagt, dass Gedächtnisverluste bei den Überlebenden von Gnomeregan sehr häufig vorkommen.\n\nHochtüftler Mekkadrill ist der Anführer aller Gnome. Er hat es sich zur Gewohnheit gemacht, jeden geretteten Überlebenden persönlich kennenzulernen. Ihr solltet Euch ihm vorstellen. Er befindet sich bei seinem Kriegsrat in dem Zelt mitten in der Stadt.", sourceObjective = "Stellt Euch bei Hochtüftler Mekkadrill in Neu-Tüftlerstadt vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[31138] = { id = 31138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Künste eines Mönchs", description = "Wenn Ihr kämpft, werdet Ihr bessere Fähigkeiten erhalten. Mit wachsenden Fähigkeiten werdet Ihr neue Techniken erlernen. Zieht los, seht Euch um, lernt und zeigt mir, was Ihr herausgefunden habt.", sourceObjective = "Ihr müsst Stufe 3 erreichen, um Tigerklaue zu erlernen. Wenn Ihr sie gelernt habt, wendet sie zweimal auf eine Trainingsattrappe in Neu-Tüftlerstadt an.", sourceObjectiveStatus = "unverified-source-field" }
quests[31139] = { id = 31139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlagt sie zurück!", description = "Ihr seid also der neue Rekrut aus Sturmwind, wie? Ich bin Marschall McBride, Kommandant dieser Garnison. Ich bin froh, Euch an Bord zu haben...\n\n<McBride sieht ein paar Zettel durch.>\n\n{name}. Ihr seid {name}, ja?\n\nIhr seid genau zur rechten Zeit gekommen. Die Schwarzfelsorcs haben es geschafft, sich durch einen Spalt im Felsen in den Nordhain einzuschleichen. Meine Soldaten tun ihr Bestes, sie zurückzuschlagen, aber ich fürchte, sie werden bald übermannt werden.\n\nBegebt Euch nach Nordwesten in den Wald und tötet die angreifenden Schwarzfelsworgs! Helft meinen Soldaten!", sourceObjective = "Tötet 6 Kampfworgs des Schwarzfels.", progress = "Habt Ihr die Kampfworgs des Schwarzfels zurückgeschlagen?", completion = "Ihr habt uns ein wenig Zeit verschafft, {name}, aber wir haben jetzt ein noch größeres Problem, um das wir uns kümmern müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31140] = { id = 31140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgs im Schafspelz", description = "Die einfallenden Orcs sind keine Narren. Sie schätzen uns ab, stellen sicher, dass ihre Angriffe zu ihrem Vorteil sein werden.\n\nIm Wald nordwestlich von hier lauern Spione der Schwarzfelsorcs. Sie kundschaften uns mit ihren Handfernrohren aus, überwachen jeden unserer Schritte - und warten. Ich will, dass Ihr sie angreift!\n\nTötet die Spione der Schwarzfelsorcs! Wir müssen ihnen zeigen, dass wir sehr wohl wissen, dass sie uns beobachten und dass wir vorbereitet sind!", sourceObjective = "Tötet 8 Spione der Schwarzfelsorcs.", completion = "Hervorragende Arbeit, {name}. Es hat sich herausgestellt, dass Ihr ein echter Gewinn für die Garnison seid. Es wird Zeit für Eure Ausbildung!", sourceObjectiveStatus = "unverified-source-field" }
quests[31141] = { id = 31141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalligrafiebrief", description = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr mit den Schwarzfelsspionen fertiggeworden seid, {name}. Es scheint sich um einen versiegelten Brief mit den Insignien von Bao zu handeln, einem Pandaren, der aus einem weitentfernten Land zu uns gekommen ist. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", sourceObjective = "Lest den Kalligrafiebrief und sprecht mit Bao in der Abtei von Nordhain.", progress = "Ah, Ihr habt meinen Brief erhalten, {name}... gut.\n\nIch bin von weit her gekommen, um Eurem Volk in den Lehren der Mönche zu unterrichten.", completion = "Ich bin von weit her gekommen, um die Gebräuche Eures Volkes zu erlernen. Zögert nicht, zu mir zu kommen, damit ich unterweisen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[31142] = { id = 31142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tigerklaue", description = "Jetzt, da Ihr Gelegenheit hattet, Eure Fähigkeiten im Kampf zu erproben, wird es Zeit, Euch noch einen Grund vorzustellen, warum das Üben so wichtig ist.\n\nWenn Ihr nämlich mehr Erfahrung sammelt, könnt Ihr bald Techniken beherrschen, die Ihr Euch jetzt nicht zutrauen würdet.\n\nAlso macht Euch auf und sammelt noch etwas mehr Erfahrung. Erlernt eine neue Fähigkeit und zeigt sie mir an einer der Trainingsattrappen.", sourceObjective = "Erreicht Stufe 3, um 'Tigerklaue' zu erlernen. Dann übt die Anwendung von 'Tigerklaue' an einer Trainingsattrappe südlich des Eingangs zur Abtei von Nordhain.", completion = "Ihr lernt schnell, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31143] = { id = 31143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stürzt Euch in die Schlacht!", description = "Während Ihr unterwegs wart, um zu trainieren, habe ich eine dringliche Nachricht von Stellvertreter Willem erhalten. Wie sich herausstellt, haben die Schwarzfelsorcs goblinische Auftragsmörder angeheuert. Sie haben unser Bataillon hinter der Abtei aus dem Hinterhalt angegriffen. Willem bat mich, ihm einen Helden zu schicken. Ihr müsst ihnen helfen, {name}!\n\nFindet Stellvertreter Willem nördlich der Abtei am Kommandozelt. Geht!", sourceObjective = "Meldet Euch bei Stellvertreter Willem hinter der Abtei von Nordhain im Wald von Elwynn.", completion = "Es stimmt, man hat uns aus dem Hinterhalt angegriffen. Ich wage es nicht, noch weitere Soldaten dort hinauszuschicken und zu riskieren, sie auch noch zu verlieren. Ich brauche einen Freiwilligen. Jemanden, der bereit ist, sein Leben zu riskieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[31144] = { id = 31144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben Auftragsmörder losgeschickt", description = "Habt Ihr jemals einen Goblin gesehen, {name}? Diese jämmerlichen, kleinen, grünhäutigen Monster mögen nur zwei Dinge: Gold und sich selbst.\n\nDie Schwarzfelsorcs haben sich goblinische Auftragsmörder zu Hilfe geholt, die unsere Soldaten töten sollen. Wenn Ihr zum Feld im Norden blickt, könnt Ihr schwach ihre Umrisse erkennen, wie sie im Gras umherschleichen.\n\nIhr müsst Euch dort hinbegeben und jeden Goblin töten, den Ihr zu Gesicht bekommt. Sie müssen kapieren, dass man sich nicht mit der Allianz anlegt!", sourceObjective = "Tötet 8 goblinische Auftragsmörder.", completion = "Ihr habt diesen Monstern eine Lektion erteilt! Sie werden es sich zweimal überlegen, bevor sie noch einen Mordauftrag der Orcs annehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31145] = { id = 31145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefahr gebannt", description = "Ausgezeichnete Arbeit, {name}! Sie werden uns definitiv nicht mehr in den Rücken fallen. Wir kümmern uns um die Nachzügler. Ich will, dass Ihr zurück zu Marschall McBride geht, der südlich von hier vor der Abtei von Nordhain steht. Lasst ihn wissen, dass die Situation mit den Goblins unter Kontrolle ist.\n\nLebt wohl, {class}.", sourceObjective = "Meldet Euch bei Marschall McBride vor der Abtei von Nordhain im Wald von Elwynn.", completion = "Dank Eurer Hilfe ist es uns gelungen, die nördlichen und westlichen Abschnitte von Nordhain zu sichern. Dennoch gibt es im Osten noch immer eine ziemlich große Ansammlung von Schwarzfeslorcs und sie haben damit begonnen, den Wald niederzubrennen!", sourceObjectiveStatus = "unverified-source-field" }
quests[31146] = { id = 31146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bekritzelte Schriftrolle", description = "Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Der Pandarenbesucher, Ting, hat sie geschickt. Vielleicht können Mönche solchen Müll entziffern, ich kann das nicht. Ihr solltet mit ihr sprechen. Sie ist im Gasthaus, auf der anderen Seite der Straße.", sourceObjective = "Lest die elegante Schriftrolle und sprecht mit Ting der Bauchstarken in Todesend.", sourceObjectiveStatus = "unverified-source-field" }
quests[31147] = { id = 31147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tigerklaue", description = "Wenn Ihr auf Eurem Weg, der inneren und äußeren Anforderungen Herr zu werden, große Herausforderungen meistert, werdet Ihr neue, tief in Euch verborgene Fähigkeiten entdecken. Geht jetzt und macht Euch selbst zum Meister. Entdeckt die Technik der Tigerklaue. Geht dann und übt sie an einer Trainingsattrappe.", sourceObjective = "Erreicht Stufe 3, um 'Tigerklaue' zu erlernen und übt die Fähigkeit an einer Trainingsattrappe.", sourceObjectiveStatus = "unverified-source-field" }
quests[31148] = { id = 31148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Novizin Elreth", description = "Ach, bevor ich gehe - Ihr solltet mit Novizin Elreth sprechen. Sie hat Arbeit für Euch, und es wäre gut für Euch, wenn Ihr anderen helft und Eure Fähigkeiten verbessert.\n\nWenn Ihr mich das nächste Mal sucht, findet Ihr mich in Unterstadt.", sourceObjective = "Sprecht mit Novizin Elreth in Todesend in Tirisfal.", sourceObjectiveStatus = "unverified-source-field" }
quests[31150] = { id = 31150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elegante Rune", description = "{name}, diese Rune wurde mir gegeben, damit ich sie an Euch weiterreiche. Nehmt Euch einen Moment Zeit, sie bei Gelegenheit zu lesen. Ich denke mal, sie kommt von unserem weit gereisten Besucher Lo. Werft doch am besten einen Blick darauf und sucht ihn in Ambossar auf.", sourceObjective = "Lest die elegante Rune und sprecht mit Lo im Eisklammtal.", sourceObjectiveStatus = "unverified-source-field" }
quests[31151] = { id = 31151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treten & Schlagen - nur eine Frage der Konzentration", description = "Die Wahrheit ist, dass Ihr bereits über das Talent und die Fähigkeiten verfügt, um alle notwendigen Dinge zu erlernen. Ich kann Euch nur den Weg zu diesem Wissen weisen.\n\nZunächst einmal müsst Ihr üben, bis Ihr eine neue Technik zu verstehen beginnt. Die erste Technik, die Ihr lernen werdet, ist die Tigerklaue. Also zieht los, lernt weiter, bis Ihr Euer ganzes Potenzial entdeckt habt und dann übt Eure neue Technik!\n\nUnd denkt daran: Es ist alles nur eine Frage der Konzentration!", sourceObjective = "Erreicht Stufe 3, um die Technik Tigerklaue zu erlernen und übt dann diese Fähigkeit an einer der Trainingsattrappen vor dem Eingang nach Ambossar.", sourceObjectiveStatus = "unverified-source-field" }
quests[31152] = { id = 31152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Blick in die Vergangenheit", description = "Gleich, gleich. Lasst mich meine Sachen zusammensammeln.\n\nWollen doch nicht, dass ich jetzt meine Aufzeichnungen verliere, oder? Ganz besonders nicht, nachdem Ihr für sie Euer Leben riskiert habt!\n\nGut, fertig. Lasst uns aufbrechen.\n\nIch muss schon sagen, dass es sich viel sicherer anfühlt, gemeinsam mit Euch zu reisen, so, wie Ihr mit diesem Saurok umgegangen seid!", sourceObjective = "Sprecht mit Lehrensucher Cho am Ring der Steine.", completion = "Ich bin meinen Vorfahren für das Wissen, das sie an mich weitergegeben haben, sehr dankbar.\n\nIch stehe auf ihren Schultern.", sourceObjectiveStatus = "unverified-source-field" }
quests[31156] = { id = 31156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalligrafiepergament", description = "Ah, während Ihr weg wart, ist ein Pergament für Euch gekommen, {name}.\n\nLest es, wenn Ihr die Zeit habt. Wenn ich mich nicht irre, kommt es von unserem Pandarenfreund, Gato. Er ist von weit entfernt zu uns gekommen und gewährt uns die Ehre seiner Weisheit und die Ausbildung als Mönch. Macht Eurem Volk keine Schande, indem Ihr bei seinen Lektionen versagt!", sourceObjective = "Lest das Kalligrafiepergament und sprecht mit Gato im Tal der Prüfungen.", progress = "Ahh, Ihr seid gekommen.", completion = "Wir werden unseren jeweiligen Völkern Ehre erweisen, indem wir voneinander lernen. Ihr werdet ein großer {class} werden, wenn ich irgendetwas zu sagen habe. Und ich werde die Gepflogenheiten Eures Volkes kennenlernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31157] = { id = 31157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tigerklaue", description = "Während Ihr den Weg Eurer Ausbildung beschreitet, werdet Ihr feststellen, dass Ihr in Euch die Macht tragt, neue Techniken zu erlernen. Ihr müsst sie noch nicht einmal von mir oder einem erfahreneren Mönch - Ihr werdet sehen, dass Ihr sie ganz alleine in Euch findet.\n\nGeht und übt Euch in den Grundlagen. Sammelt mehr Erfahrung und entwickelt eine neue Technik - sobald es soweit ist, könnt Ihr sie an einer Trainingsattrappe üben.", sourceObjective = "Erreicht Stufe 3, um 'Tigerklaue' zu erlernen. Findet eine Trainingsattrappe und übt daran 2-mal die Anwendung von 'Tigerklaue'.", completion = "Gut, gut, Eure erste Herausforderung habt Ihr gemeistert. Wir werden viel voneinander lernen, das sehe ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[31158] = { id = 31158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grundlagen: Dinge schlagen", description = "Alles klar, Mann. Fangen wir mit den Grundlagen an. Ich muss wissen, dass Ihr auch versteht, wie Ihr die Waffe zu schwingen habt, mit der Ihr da rumfuchtelt.\n\nGeht und zerstört diese Tikiziele. Geht es langsam an. Natürlich. Ich beobachte Eure Form und dann sehen wir weiter.", sourceObjective = "Zerstört 6 Tikiziele.", completion = "Nicht schlecht, Mann. Es liegt eine natürliche Grazie in Euren Schwüngen... Ihr habt womöglich Talent.\n\nEin paar Ecken und Kanten sind natürlich noch zu glätten, aber ich werde Euch noch einiges beibringen in nächster Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[31159] = { id = 31159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Dunkelspeere", description = "Die Trolle des Dunkelspeerstamms war'n lange Zeit Opfer. Ausgestoßene. Immer wieder musst'n wir flieh'n und unser Zuhause verlass'n. Aber diesmal hat uns nich' die Flucht hierher getrieb'n.\n\nVol'jin hat uns Führung durch Weisheit angeboten und das hat uns bisher am Leben erhalt'n. Nun bietet uns diese Weisheit Vorzeich'n einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal flieh'n wir nicht. Diesmal kämpf'n wir für ein Zuhause, das besteh'n bleibt.\n\nEs ist Zeit, mit der Ausbildung zu beginnen, {name}. Sprecht mit Zabrax im Osten.", sourceObjective = "Trefft Zabrax auf dem Ausbildungsgelände der Dunkelspeere.", completion = "Noch so ein Jungblut, wie?\n\nObwohl, Ihr seht aus, als wärt Ihr gut in Form. Ruhige Hände. Scharfe Augen. Vielleicht wird aus Euch noch ein echter {class}.\n\nLasst uns keine Zeit mehr verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[31160] = { id = 31160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aller Anfang ist schwer", description = "Woll'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.\n\nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.\n\nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!", sourceObjective = "Sammelt 6 Felle einer Wildmähnenkatze.", progress = "Sie sind sicher keine große Herausforderung, Mann, aber sie können einem ganz schön die Knöchel zerkratzen, wenn man nicht schnell genug auf den Beinen ist.", completion = "Das sind nette Pelzchen, Mädel. Die geben sicher 'n paar mächtige Mäntel ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[31161] = { id = 31161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grube der Bewährung", description = "Ihr habt Euch ganz schön gemausert, {class}. Ich bin sicher, ich könnte Euch hier und da einen Trick oder zwei beibringen, aber ich werde Eure Zeit nicht mehr mit Tikizielen verschwenden.\n\nIch habe also eine letzte Prüfung für Euch, Mann. Geht rüber zur Grube in der Mitte von diesem Gebiet und kämpft gegen einen echten Fiesling - einen, der Euch auch umbringen will. Lasst es den Gefängniswärter wissen, wenn Ihr bereit seid.", sourceObjective = "Redet mit einem Gefängnisaufseher der Dunkelspeere, betretet dann die Grube der Bewährung und besiegt einen gefangenen Späher der Gallschuppen.", progress = "Jeder Troll muss sich beweisen, bevor er das Trainingsgelände verlassen darf.", completion = "Ihr seid sehr gut in Form. Eines Tages werdet Ihr sehr mächtig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[31162] = { id = 31162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Künste eines Mönchs", description = "Wenn Ihr besser kämpfen lernt, findet Ihr Sachen heraus, an die Ihr vorher nie gedacht hättet.\n\nWollt Ihr es sehen? Los, trainiert fleißig und lernt etwas Neues.\n\nKommt dann wieder und zeigt es mir.", sourceObjective = "Ihr müsst Stufe 3 erreichen, um Tigerklaue zu erlernen. Übt, indem Ihr die Tigerklaue gegen ein Tikiziel einsetzt.", completion = "Gute Arbeit, Mann! Das schien Euch ja wirklich leicht zu fallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31163] = { id = 31163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als erwartet", description = "Ihr bringt auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, es gibt noch mehr wichtige Sachen, bei denen wir Eure Fähigkeiten gebrauchen können. Ihr müsst nicht mehr mit dem Nachwuchs herumhängen.\n\nGeht zum Dorf im Südosten und stellt Euch vor. Helft hier und da und ich bin sicher, dass Ihr schnell aufsteigen und mehr Ansehen erlangen werdet.", sourceObjective = "Meldet Euch bei Vol'jin in der Dunkelspeerfeste.", completion = "Ihr seid der neue Rekrut, von dem alle reden, hm? Willkommen bei den Dunkelspeeren.", sourceObjectiveStatus = "unverified-source-field" }
quests[31165] = { id = 31165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalligrafienotiz", description = "Gerade eben fragte eine Botin nach Euch, {name}. Ich glaube, sie wurde von unserem Pandarengast, Shoyu, geschickt. Wenn dem so ist, würde ich sie schnellstens lesen.", sourceObjective = "Lest die Kalligrafienotiz und sprecht mit Shoyu im Camp Narache.", sourceObjectiveStatus = "unverified-source-field" }
quests[31166] = { id = 31166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tigerklaue", description = "Bis jetzt habt Ihr Euch wacker geschlagen. Je weiter Euer Weg Euch führt, desto stärker werdet Ihr. Ihr erlernt dann Techniken, von denen Ihr zuvor nicht einmal zu träumen gewagt habt.\n\nEure erste Lektion wird die Macht der Erfahrung sein. Geht, erlernt eine neue Fähigkeit und führt sie mir dann vor.", sourceObjective = "Ihr müsst Stufe 3 erreichen, um Tigerklaue zu erlernen. Sucht eine Trainingsattrappe in Camp Narache und übt daran.", sourceObjectiveStatus = "unverified-source-field" }
quests[31167] = { id = 31167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stammbaum", description = "Nun wisst Ihr also Bescheid, <Reisender/Reisende>, oder zumindest wisst Ihr so viel, wie für eine vernünftige Vorstellung notwendig ist.\n\nUnd wie steht es um Euch? Unterscheidet sich Euer Volk tatsächlich so sehr von dem meinen?\n\nEs muss doch ganz bestimmt Dinge geben, die uns gemein sind. Schauen wir doch mal...", sourceObjective = "Zündet das Räucherwerk am Ring der Steine an.", progress = "Ein wunderschöner Tag, findet Ihr nicht?", completion = "Doch nicht so unterschiedlich, Ihr und ich.\n\nIch glaube, dass wir gute Freunde werden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[31168] = { id = 31168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalligrafiesiegel", description = "Dieses Siegelzeichen wurde mir durch einen Boten von unserem Pandarengast, Laoxi, überreicht. Es sieht so aus, als wollte er ein paar Worte mit Euch wechseln, wenn Ihr Zeit habt. Lest es und bringt es dann zu ihr.", sourceObjective = "Sprecht mit Laoxi in Aldrassil im Laubschattental.", progress = "Ah, Ihr seid gekommen. Gut.\n\nIch lerne so viel - Euer Volk verfügt über einen Schatz an Wissen, der mit nichts vergleichbar ist, was ich bisher gesehen habe. So klein ich mich im Angesicht dieses Umstands auch fühle, so sehr hoffe ich doch, dass auch ich Euch etwas lehren kann.", completion = "Man hat mich gewarnt, dass nicht alle Eures Volkes Fremde willkommen heißen würden, doch habe ich festgestellt, dass das Gegenteil wahr ist - man hat mich nicht nur aufgenommen, ich durfte auch so viel von Euch lernen.\n\nIhr macht einen vielversprechenden Eindruck als junger {class} und ich hoffe, dass ich Euch viel von unseren Gebräuchen beibringen kann, so wie Euer Volk mich so viel über ihre gelehrt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[31169] = { id = 31169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kunst der Mönche", description = "Das wahre Geheimnis des Mönchs besteht darin, das Wissen und die Macht freizusetzen, die in einem selbst schlummern.\n\nGeht los, sammelt weitere Erfahrungen, und erlernt eine neue Fähigkeit. Demonstriert sie dann an einer der Trainingsattrappen.", sourceObjective = "Ihr müsst Stufe 3 erreichen, um Tigerklaue zu erlernen. Sucht nach einer Trainingsattrappe und übt daran die Anwendung von Tigerklaue.", completion = "Ihr habt Euch als fähig erwiesen. Wenn es an der Zeit ist, Eure Ausbildung fortzusetzen, kehrt zu mir zurück und ich werde Euch neue Techniken lehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[31170] = { id = 31170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung zum Mönch", description = "Während Ihr in Eurer Klasse weiter aufsteigt, werdet Ihr sicher die Ausbildung, die Euch der Lehrer Eurer Klasse anbietet, nutzen wollen. Für junge Mönche ist hier auf der Insel der Sonnenwanderer Pao zuständig, unser Pandarengast. Sprecht mit ihr und seht, was sie Euch an Ausbildung anbieten kann.\n\nPao - wie alle anderen Lehrer auf der Insel der Sonnenwanderer auch - ist innerhalb des Sonnenturms auf der unteren Ebene anzutreffen.", sourceObjective = "Sprecht mit Pao - dem Mönchlehrer - innerhalb des Sonnenturms auf der Insel der Sonnenwanderer.", sourceObjectiveStatus = "unverified-source-field" }
quests[31171] = { id = 31171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tigerklaue", description = "Gut. Das war ein vielversprechender Anfang. Vor Euch liegt noch ein langer Weg. Aber je weiter ihr voranschreitet, desto mehr Dinge lernt Ihr, von denen Ihr zuvor nicht einmal zu träumen gewagt hättet.\n\nSammelt noch etwas mehr Erfahrung und erlernt eine neue Technik. Sucht Euch dann eine Trainingsattrappe und demonstriert Eure neue Fähigkeit.", sourceObjective = "Erreicht Stufe 3 und erlernt Tigerklaue. Findet eine Trainingsattrappe außerhalb des Sonnenturms und übt diese Fähigkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[31172] = { id = 31172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung zum Mönch" }
quests[31173] = { id = 31173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tigerklaue", description = "Ich hoffe, Euren Leuten geht es gut... Dieser Absturz war ja unglaublich laut. Was für ein Chaos!\n\n<Mojo betrachtet Euch, um Euer Potenzial einzuschätzen.>\n\nJa, mit Euch kann man etwas anfangen. Sie sagen mir, dass sie mehr Kämpfer brauchen, aber sie wollen auch nicht, dass ich zu Schaden komme. Ich habe zwar keine Angst, aber ich will mich auch nicht einmischen. Also werde ich Euch unterweisen.\n\nWie Ihr wohl schon festgestellt habt, steigen Eure Fähigkeiten mit zunehmender Erfahrung. Also zieht los und versucht, eine neue Fähigkeit zu meistern. Los, zeigt's mir. Ihr bekommt das schon hin.", sourceObjective = "Erreicht Stufe 3, um die Technik Tigerklaue zu erlernen. Sucht eine Trainingsattrappe an der nordwestlichen Seite der Absturzstelle und übt diese Fähigkeit.", completion = "Ihr solltet diese Technik immer anwendungsbereit halten, {name}. Damit könnt Ihr stärkere Gegner außer Gefecht setzen oder Euch einfach nur großartig fühlen - wie ein Tiger eben.", sourceObjectiveStatus = "unverified-source-field" }
quests[31175] = { id = 31175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skeer der Blutsucher", description = "Unsere Anstrengungen, die Untiefen vor den Zan'vess zu erobern, haben sich gelohnt.\n\nWir haben noch einen in Bern begrabenen Getreuen entdeckt, versteckt in den Wassern im Südwesten.\n\nUnsere Reihen mit einem weiteren Getreuen zu verstärken ist überlebenswichtig. Mit noch einem Held aus vergangenen Zeiten könnte sich das Blatt zu unseren Gunsten wenden.\n\nIch würde ja sofort gehen, doch leider werde ich hier gebraucht.\n\nDa Ihr bereits <ein Erwecker/eine Erweckerin> seid, könnt Ihr diese Aufgabe für mich übernehmen.", sourceObjective = "Erweckt Skeer den Blutsucher in der Unterwasserhöhle.", completion = "Der Hunger... man hat mir gesagt, dass er heftig sein würde, so habe ich ihn mir aber nicht vorgestellt.\n\nEs ist merkwürdig, sich so... schwach zu fühlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31176] = { id = 31176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Merkwürdige Gelüste", description = "Essen. Ich muss essen.\n\nZu meiner Zeit wurde man von Seesternfleisch nicht nur stark, sondern bekam auch einen klaren Kopf. Also muss ich genau das essen.\n\nBringt mir welches aus den Untiefen in der Nähe.\n\nWenn Ihr noch länger wartet, werde ich stattdessen Euch verschlingen.", sourceObjective = "Sammelt 12 Portionen Seesternfleisch.", progress = "Die Säfte des Seesterns werden mir Klarheit verschaffen.", completion = "Ja, gebt es her! Gut gemacht, Erwecker.", sourceObjectiveStatus = "unverified-source-field" }
quests[31177] = { id = 31177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schick essen", description = "Zu Lebzeiten war ich der beste Krieger des Schwarms.\n\nHelft mir wieder zu Kräften zu kommen, und ich werde es Euch beweisen.\n\nIch kann Meeressalz in der Nähe riechen, und wo das Meer ist, da gibt es auch Salzklacker.\n\nBringt mir ihre Schwänze. Ich muss mich an ihrem Fleisch gütlich tun.", sourceObjective = "Sammelt 8 Klackerschwänze.", progress = "Ich habe viel zu tun. Je eher ich kämpfen kann, desto eher kann ich zum Rat zurückkehren.", completion = "Ausgezeichnet. Das wird mir die Kraft geben, meine Gegner zu bezwingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31178] = { id = 31178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein blutiges Vergnügen", description = "Ein Krieger ist erst dann zum Kampf bereit, wenn er das Blut seiner Feinde schmeckt.\n\nIch bin immer noch zu schwach für die Jagd, also müsst Ihr meinen Platz einnehmen.\n\nEs muss das Blut von Raubtieren und Wilden sein. Ich kann sie im Wasser vor dieser Höhle draußen riechen!\n\nBringt es mir und Ihr werdet vielleicht die Macht des Blutsuchers zu sehen bekommen.", sourceObjective = "Sammelt 100 Einheiten flüchtiges Blut von Schreckensschiffshaltern.", progress = "Durch das Trinken des Blutes Eurer Gegner erlangt Ihr ihre Stärke.", completion = "Ja, dieses Blut wird seinen Zweck erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31179] = { id = 31179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geruch des Blutes", description = "Ich fürchte, ich habe mir die Hände mit Saurokblut schmutzig gemacht, während Ihr fort wart.\n\nTut mir leid, aber ich konnte einfach nicht anders.Und jetzt seht zu, wie sie mich angreifen.\n\nLächerlich!\n\nWollen sie sich damit für ihre Gefallenen rächen? Kommen sie, um MICH herauszufordern?\n\nMich, der ich hundert Kriege gewonnen habe? Mich, der ich mich im Alleingang Tausenden entgegengestellt und trotzdem meinen Feinden zugerufen habe, näherzukommen?\n\nNein, diese... Saurok... werden vor mir in sich zusammenfallen wie Papier vor einer Flamme!\n\nIch werde Euch meine Macht demonstrieren, <Erwecker/Erweckerin>. Kämpft an meiner Seite und seht zu.\n\nDa kommen sie!", sourceObjective = "Tötet 12 Fleischfresser der Schlickschuppen und den Serpentus der Schlickschuppen.", completion = "Euch war einmal mehr Erfolg beschieden. Gut gemacht, Erwecker.", sourceObjectiveStatus = "unverified-source-field" }
quests[31181] = { id = 31181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frische Körbe", description = "Wir haben eine Menge leere Krabbenkörbe da draußen, die neue Köder brauchen.\n\nAlso, wir KÖNNTEN einen nach dem anderen einholen und sie ganz gemütlich hier oben mit Ködern bestücken. Auf einem bequemen Stuhl sitzen und vielleicht zum Warmhalten eine schöne heiße Tasse Tee trinken. Klingt doch schön, findet Ihr nicht?\n\nDaraus wird nichts.\n\nMacht Euch zur Einsamen Bucht, direkt im Südwesten, auf und füllt die Körbe mit zwei Teilen frischen Seemonarchen als Köder. Mit \"frisch\" meine ich solche, die direkt dort im Wasser getötet wurden.\n\nAch ja, und mit \"Körben\" meine ich Fallen. Wenn Ihr zur Besatzung gehören wollt, lernt Ihr lieber den Jargon.", sourceObjective = "Bestückt 10 leere Krabbentöpfe in der Einsamen Bucht mit Ködern. Jeder Topf erfordert 2 Seemonarchenteile.", completion = "Nicht übel, Grünschnabel, gar nicht übel.", sourceObjectiveStatus = "unverified-source-field" }
quests[31182] = { id = 31182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr wisst doch, Otter?", description = "Wisst Ihr, was den Ködern in diesen Körben zugestoßen ist?\n\nOtter. Otter sind ihnen zugestoßen.\n\nSie fressen zwar lieber frische Muscheln, wenn sie aber hungrig genug sind, räumen sie auch unsere Krabbenfallen aus.\n\nDie Otter in der Einsamen Bucht sind gesetzlich geschützt und wir sind hier ein rechtmäßiges Unternehmen. So gern ich die kleinen Ratten ein für alle Mal loswerden möchte - sorgen wir einfach dafür, dass sie keinen Hunger mehr haben und die Krabbenkörbe in Ruhe lassen.\n\nVerfüttert ein paar Muscheln an sie, damit sie beschäftigt sind, während Ihr dort draußen seid.", sourceObjective = "Benutzt den Beutel mit Muscheln, um 8 Kaltbartotter in der Einsamen Bucht zu füttern.", completion = "Das sollte ihre kleinen Schnurrhaare eine Weile von unseren Fallen fernhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[31183] = { id = 31183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Käpt'n treffen", sourceObjective = "Sprecht mit \"Tropf\" Su-Dao in Tropfs Wagnis.", completion = "Neue Deckhilfe, hm? Das werden wir noch sehen.\n\nIch halte das Ruder fest in der Hand - selbst wenn es auf dem Meeresgrund sitzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31184] = { id = 31184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alter und Verrat", description = "Also, ich hab keinen Grund, Euch zu trauen, es gibt da aber eine Aufgabe, die ich meiner Besatzung nicht geben kann.\n\nDurchsucht das Wrack unseres alten Schiffs, der Nebelhüpfer, und bringt mir ihre Charta. Sie ist in einem silbernen Rohr in einer Truhe versiegelt.\n\nSie ist etwas, äh... verfänglich. Ich kann nicht riskieren, dass jemand von der Besatzung beschließt, das alte Mädchen aufzusuchen, und sie findet. Sie ruht auf dem Riff von Mazu, westlich von hier.\n\nWenn Ihr genug Mumm habt, schlage ich vor, dass Ihr Euch von einer Rippströmung hinbringen lasst. Die findet Ihr nämlich überall auf dem Riff.", sourceObjective = "Bergt die Charta vom Wrack der Nebelhüpfer.", progress = "Ehrlich gesagt hoffe ich, dass die alte Charta von einem Barsch aufgefressen wurde.\n\nAndererseits könnte er dann trotzdem wieder hier landen. Verflixt!", completion = "Ja, das ist das Rohr mit der Charta. Ihr würdet wohl gern wissen, was es mit dem ganzen Getue auf sich hat, stimmt's?\n\n<Tropf seufzt tief und öffnet das Rohr.>\n\nBringen wir es hinter uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[31185] = { id = 31185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gassi mit Hund", description = "Hund ist nicht mein \"Haustier\". Er ist ein Mitglied dieser Besatzung und mein bester Freund. Hat mir mehr als einmal das Leben gerettet.\n\nIch werde aber zu alt, um ihn auszuführen, und er braucht Bewegung. Würdet Ihr eine Runde über das Riff mit Hund für mich drehen?\n\nEr schwimmt gern durch die heißen Geysire südöstlich der Untiefen.\n\nEr muss auf jeden Fall den toten Wal am westlichen Rand des Riffs... äh... \"markieren\".\n\nAch ja, und er will bestimmt auch unser altes Schiffswrack besuchen. Er schwelgt gern in Erinnerungen.", sourceObjective = "Nehmt Hund und stattet mit ihm den heißen Geysiren, dem toten Wal und dem Wrack der Nebelhüpfer auf dem Riff von Mazu einen Besuch ab.", completion = "Wie ist es gelaufen? Ich hoffe, er hat Euch keine große Mühe bereitet!", sourceObjectiveStatus = "unverified-source-field" }
quests[31186] = { id = 31186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hundefutter", description = "<Hund bellt in bester Löwenrobbenmanier und deutet kraftlos mit einer Flosse auf sein enormes Maul.\n\nEr hat Hunger.\n\nDas Riff von Mazu ist mit Felsschalenschnappklauen bedeckt, die eine leckere Mahlzeit für ihn abgeben dürften.>", sourceObjective = "Helft Hund, die Reste von 10 Felsschalenschnappklauen zu essen.", progress = "<Das ist mit Sicherheit die erbärmlichste Löwenrobbe, die Ihr je gesehen habt.>", completion = "<Hund leckt sich zufrieden die Lefzen und sieht glücklich aus.>", sourceObjectiveStatus = "unverified-source-field" }
quests[31187] = { id = 31187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krabbenfülle", description = "Ich habe gerade gehört, dass ein paar von den Körben, die wir heute Morgen ausgeworfen haben, einen Volltreffer gelandet haben. Massenweise Krabben!\n\nDummerweise ist die Rippströmung stärker geworden und wir haben die Spur von einigen Körben verloren. Und die sitzen jetzt da draußen, gefüllt mit stacheligem blauem GOLD!\n\nIch will Euch da draußen sehen. Hängt an jede volle Falle, die Ihr findet, eine von diesen Bojen und schickt sie für uns an die Oberfläche.", sourceObjective = "Hängt eine Nebelhüpferboje an 8 volle Krabbenkörbe auf dem Riff von Mazu.", completion = "Gute Arbeit dort draußen!", sourceObjectiveStatus = "unverified-source-field" }
quests[31188] = { id = 31188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haiwoche", description = "Der Krabbenfang ist unsere größte Einkommensquelle, wir schicken aber alle möglichen Güter hinter die Mauer zurück. Öl, Pflanzen, sogar seltene Mineralien - hier draußen ist das Meer freigiebig!\n\nMomentan sind Drescherzähne der letzte Schrei auf den Märkten zu Hause. Angeblich eignen sie sich hervorragend für Halsketten.\n\nDas Riff von Mazu im Westen wimmelt nur so von Dreschern. Bringt mir massenweise Zähne!", sourceObjective = "Sammelt 200 Drescherzähne, indem Ihr sie den Langflossendreschern auf dem Riff von Mazu zieht.", progress = "Ich habe selbst gesehen, wie jemand von einem Drescher aufgefressen wurde; deshalb verstehe ich nicht ganz, warum man aus freien Stücken ihre Zähne um den Hals tragen sollte, aber egal.", completion = "Die hier sind perfekt. Legt sie einfach dort drüben hin. Ich würde sie lieber nicht selbst anfassen. Davon kriege ich eine Gänsehaut.", sourceObjectiveStatus = "unverified-source-field" }
quests[31189] = { id = 31189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einholstrategie", description = "Ich hätte nie gedacht, dass ich den Tag erleben würde, doch zum ersten Mal seit... na, zum ersten Mal ÜBERHAUPT hat mich Meisterangler Ju Lien um Hilfe mit seinen Angelleinen gebeten.\n\nAnscheinend spielt die See heute verrückt und er kann nicht Schritt halten. Seht nach, ob Ihr ihm helfen könnt. Er fischt nicht weit südlich von hier.", sourceObjective = "Helft Meisterangler Ju Lien in Tropfs Wagnis.", progress = "Geht und helft Ju Lien aus, ja?", completion = "Was ist da draußen passiert? Ich habe einen Schrei gehört, und ehe ich mich versah, kamen diese grässlichen Dinger mit der nächsten Welle an!", sourceObjectiveStatus = "unverified-source-field" }
quests[31190] = { id = 31190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rache des Seemanns", description = "Ich sitz doch in keinem verfluchten Schaukelstuhl, während meine Besatzung von einem Leviathan verschlungen wird!\n\nLos, wir gehen zum Dock und lassen eine Jolle zu Wasser. Ich habe eine spezielle, genau für diese Art von Situation. Meine eigene kleine Nebelhüpfer Jr.\n\nWir werden diesem Ding einen Fall von Harpunenfieber verpassen.", sourceObjective = "Lasst die Nebelhüpfer Jr. am Dock in Tropfs Wagnis zu Wasser und benutzt sie, um Jiao zu erledigen.", completion = "Gut geschossen dort draußen!\n\nIch wusste, dass wir es schaffen würden. Mir ist noch nie etwas begegnet, das man nicht mit genügend Harpunen hätte töten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[31194] = { id = 31194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlängelschuppen unterdrücken", description = "Die Schlängelschuppen gehorchen ihrem Anführer, dem Echsenlord der Schlängelschuppen. Ihr könnt ihn ganz im Südwesten der Windwärtsinsel dabei finden, wie er seine Siege feiert.\n\nWenn wir diesen Anführer ausschalten können, treffen wir ihren Stamm empfindlich.\n\nOhne ihn werden es sich die Schlängelschuppen zweimal überlegen, ob sie die friedlichen Wolkenschlangen im Osten weiterhin angreifen.", sourceObjective = "Tötet den Echsenlord der Schlängelschuppen.", completion = "Wunderbar! Ich wusste, dass Ihr den Lord der Schlängelschuppen besiegen könntet.", sourceObjectiveStatus = "unverified-source-field" }
quests[31196] = { id = 31196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sra'vess-Drecksarbeit", description = "Die Mantis sind deutlich in der Überzahl - Hunderte von ihnen gegen einen von uns.\n\nUnd sie bedrohen uns von zwei Seiten. Bei Gao-Ran im Süden können wir sie aufhalten, aber im Westen, auf der Insel, die sie Sra'vess nennen, sammeln sie sich weiterhin ungehindert.\n\nDa wir nicht blöd sind, werden wir keinen frontalen Großangriff auf sie starten. Wir können nicht an mehreren Fronten mit voller Kraft kämpfen.\n\nStattdessen werden wir Euch und einen unserer Wukao entsenden, um ein wenig Drecksarbeit zu erledigen. Klingt doch spaßig, oder?", sourceObjective = "Tötet 15 der nicht zur Elite zählenden Mantis bei Sra'vess.", completion = "Gute Arbeit. Ich halte es immer für das Beste, dann zuzuschlagen, wenn sie nicht vorbereitet sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[31197] = { id = 31197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer auf die Großen", description = "Die kleineren Mantis zu töten dient mehr der Ablenkung. Dadurch müssen sie erst wieder ihre Reihen füllen, bevor sie eine größere Offensive wagen können.\n\nWenn es uns allerdings gelingt, einige ihrer größeren Exemplare zu töten, würden wir ihre Operationen auf der Insel empfindlich stören und uns wertvolle Zeit verschaffen. Bei den Mantis steht ihre Größe in direktem Zusammenhang mit ihrer Bedeutung für das Reich.\n\nAlso tötet da draußen ein paar von den größeren Mantis für mich.", sourceObjective = "Tötet 4 Elitemantis auf Sra'vess.", completion = "Sehr, sehr gute Arbeit. Das sollte uns zumindest für ein paar Tage etwas Luft verschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31198] = { id = 31198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schlag für ihre Moral", description = "Die Mantis haben Statuen auf Sra'vess errichtet. Wir wissen allerdings nicht, welchem Zweck sie dienen. Vielleicht sind sie von religiöser Bedeutung oder sie nutzen sie für ihre Schallwellenkommunikation.\n\nIm Kampf gegen den Feind ist es wichtig, ihm nicht nur körperlichen, sondern auch mentalen Schaden zuzufügen. Was immer diese Statuen darstellen, sie scheinen den Mantis wichtig zu sein.\n\nUnd darum will ich, dass Ihr sie in die Luft jagt. So etwas Wichtiges zu verlieren, sollte ihrer Moral einen herben Schlag versetzen.", sourceObjective = "Zerstört den südlichen, mittleren, östlichen und westlichen Götzen auf Sra'vess.", progress = "Die Statuen?", completion = "Ich wette, der Verlust der Statuen hat ihnen nicht gefallen, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[31199] = { id = 31199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstörung der Belagerungsgeschütze", description = "Die Mantis greifen nicht nur in Schwärmen an. \n\nSie sind intelligent. Sie nutzen Alchemie, Bomben... und sogar Belagerungsgeschütze mit verheerender Angriffskraft.\n\nWir haben Berichte erhalten, dass sie auf Sra'vess im Westen eine Streitmacht mit Belagerungstruppen zusammenziehen. Also zieht los und zerstört diese Dinger.", sourceObjective = "Zerstört die vier Mantis-Belagerungswaffen auf Sra'vess in der Tonlongsteppe.", completion = "Diese Belagerungsgeschütze stellen erst einmal kein Problem mehr dar. Vielleicht bauen sie neue, aber vorerst haben wir uns etwas Zeit verschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[31200] = { id = 31200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausräucherung", description = "Unsere Alchemisten haben ein paar Gasbomben gebastelt, die dafür sorgen werden, dass die Mantis die Orte meiden, an denen wir sie hochgehen lassen. \n\nWenn wir sie an strategisch wichtigen Punkten auf Sra'vess platzieren, zwingen wir sie zur Evakuierung. Dadurch sorgen wir für tagelanges Chaos in den Reihen der Mantis.\n\nAlso macht Euch auf, {name}.", sourceObjective = "Platziert die Shado-Pan-Gasbomben an den 5 Zielgebäuden auf Sra'vess.", completion = "Sehr schön! Ich kann den Rauch ja sogar von hier sehen. Das sollte ein hübsches Chaos verursachen!", sourceObjectiveStatus = "unverified-source-field" }
quests[31201] = { id = 31201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freunde sind kein Fressen!", description = "Unsere Späher haben uns einen sehr alarmierenden Bericht zukommen lassen. \n\nSie haben drei unserer verschollenen Auszubildenden gefunden... \n\nSie wurden von den Mantis gefangen genommen und in ihre Kunchonggruben geworfen. \n\n...in ihre KunchongFÜTTERUNGSgruben. Glücklicherweise pflegen die Kunchong nicht so häufig zu fressen.\n\nIch möchte, dass Ihr dort eindringt und die Gefangenen mithilfe dieser Rettungsdrachen dort rausholt!", sourceObjective = "Rettet jeweils einen Shado-Pan-Auszubildenden in der nördlichen, mittleren und südlichen Kunchongfütterungsgrube.", completion = "Das sind gute Nachrichten! Ich hatte mir große Sorgen um sie gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[31203] = { id = 31203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Günstige Gelegenheit: Schwarmfürst der Sra'thik", sourceObjective = "Tötet den Schwarmfürsten der Sra'thik auf Sra'vess in der Tonlongsteppe.", progress = "Wir müssen den Schwarmfürsten ausschalten!", completion = "Ich hörte, Ihr habt Euch ein wenig... zusätzlichen Ruhm da draußen verdient. Gute Arbeit.\n\nKommt gerne an einem anderen Tag wieder vorbei. Ich bin sicher, wir werden dann wieder etwas für Euch zu tun haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[31204] = { id = 31204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Günstige Gelegenheit: Brutfürst der Sra'thik", description = "In der Nähe des Ozeans, im Osten von Sra'vess, befindet sich ein Gewölbe, das in ein ganzes Labyrinth von Höhlen führt.\n\nVon dort aus kontrolliert der Brutfürst der Sra'thik Sra'vess und schmiedet seine Pläne gegen uns. Wenn es uns gelingt, ihn auszuschalten, können wir ihre Bemühungen um Tage zurückwerfen.\n\nAlso an die Arbeit.", sourceObjective = "Tötet den Brutfürsten der Sra'thik.", progress = "Wir müssen den Brutfürsten ausschalten!", completion = "Gut gemacht, {name}! Dank Eures zusätzlichen Einsatzes haben wir jetzt etwas Ruhe vor den Mantis.\n\nAber wir werden ganz sicher auch in Zukunft Aufträge für Euch bereithalten. Kommt also gerne später wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[31206] = { id = 31206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schmelztiegel des Gemetzels: Haudrauf der Blutaugen!", description = "Eins sag ich Euch, man kann hier natürlich nicht mit den Wogenden Ebenen von Nagrand oder der Arena in Zul'Drak vergleichen, aber hey, ich bin da, wo das Gold ist! Willkommen im Schattenhochland!\n\nIhr seid neu hier, also lasst mich Euch ein paar Sachen erklären. Ich bin der Kampfveranstalter und der angriffslustige Troll hier ist Wodin, mein Leibwächter. Ihr seid meine Unterhaltung. Wenn Ihr kämpfen wollt, sagt Bescheid, und ich finde den passenden Gegner für Euch.\n\nWenn Ihr mit Freunden hier seid, können wir auch gleich anfangen! Was meint Ihr?", sourceObjective = "Betretet die Arena im Schmelztiegel des Gemetzels und besiegt Strunz'blunz!", sourceObjectiveStatus = "unverified-source-field" }
quests[31207] = { id = 31207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Arena der Auslöschung", description = "Ah, ich erinnere mich noch gut daran, damals in Nagrand aus einem Matschloch heraus Kämpfe angeführt zu haben. Wir haben schon viel mitgemacht, was, Wodin?\n\nIch sage Euch, diese Tigermönche lieben nichts mehr als eine anständige Rauferei. Sogar so sehr, dass sie mich gut bezahlt haben, um mich hier niederzulassen und die besten Kämpfer weit und breit heranzuziehen.\n\nWie wär's? Ihr und ein paar Freunde machen ein paar Runden in der Arena der Auslöschung...? Großes Geld, große Preise!", sourceObjective = "Betretet und beendet das Szenario der Arena der Auslöschung. Holt Euch anschließend Eure Belohnung von Wodin, dem Trolldiener.", progress = "Worauf wartet Ihr? Die Mönche brennen auf eine gute Show.", completion = "Gurgthock sagte, es würde sich für Euch lohnen. Sucht Euch etwas aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[31208] = { id = 31208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Giftige Absichten", description = "Wenn wir vorhaben, die Kaiserin anzugreifen, sollten wir uns bewaffnen. Ich wähle dafür eine Waffe, die von besonders giftiger Natur ist.\n\nDie Skorpione auf der Giftigen Klippe produzieren ein tödliches Gift, das sie in ihren Schwänzen aufbewahren.\n\nBringt mir ihre Stacheln und ich werde Euch zeigen, dass ich den Titel eines Getreuen zu Recht trage.", sourceObjective = "Sammelt 8 giftige Stacheln.", progress = "Habt Ihr den Stich des Giftschwanzes gespürt? Welch wundervoller Schmerz.", completion = "Gut gemacht, Erwecker. Ich hoffe, Ihr seid vorsichtig mit den Stacheln umgegangen.\n\nDas natürliche Gift dieser Skorpione ist tödlich, doch es wirkt langsam.", sourceObjectiveStatus = "unverified-source-field" }
quests[31209] = { id = 31209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finstere Schwinge, finstere Dinge", description = "Zur Erstellung meines ersten Giftes brauche ich eine weitere Zutat, <Erwecker/Erweckerin>.\n\nIhr findet sie ganz einfach bei den Skarabäen hier in der Nähe.\n\nTötet sie und bringt mir ihre Flügel.", sourceObjective = "Sammelt 150 Skarabäenflügel.", progress = "Skarabäenflügel können zerstoßen werden, um ein sehr feines und tödliches weißes Pulver herzustellen.", completion = "Ja, ausgezeichnet, Erwecker! Die hier sind perfekt.\n\nHabt Ihr Euch schon einmal überlegt, die Giftkunst zu erlernen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31210] = { id = 31210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schatten des Schreckens", description = "Die letzte Zutat ist vielleicht die tödlichste.\n\nDie Angstschattenblume wächst überall hier auf diesen Hügeln.\n\nIhr Verzehr ist dafür verantwortlich, dass die hiesigen Tiere so giftig sind.\n\nEin einziger Tropfen Angstschattennektar reicht, um das Herz eines Kunchong zum Stillstand zu bringen.\n\nZieht los und bringt mir ein paar von diesen Blumen. Lasst Euch nicht dazu verlocken, sie zu kosten.", sourceObjective = "Sammelt 8 Angstschatten.", progress = "Manchmal sind die schönsten Dinge auch die gefährlichsten.", completion = "Nicht viele würden den Wert dessen erkennen, was Ihr habt.\n\nGut gemacht, Erwecker.", sourceObjectiveStatus = "unverified-source-field" }
quests[31211] = { id = 31211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vergiftete Geist", description = "Bevor wir nach Klaxxi'vess zurückkehren, möchte ich einen Blick auf das Reich werfen. Der Rat der Klaxxi hat mir berichtet, dass der Feind sich vor dem Palast der Kaiserin sammelt.\n\nMeine Gifte sind bereit, denn wie könnte ich meine Rückkehr besser verkünden als mit Tod und Zerstörung?\n\nPasst nur auf, dass Ihr die beiden Seren nicht vermischt... zumindest nicht, solange Ihr die Gefäße noch in der Hand haltet.\n\nSprecht mit mir, wenn Ihr zum Abflug bereit seid.", sourceObjective = "Sprecht mit Xaril dem vergifteten Geist. Tötet 200 Mantis und 3 Kunchong, während Ihr mit ihm fliegt.", completion = "Danke, dass Ihr mich nach Hause zurückgebracht habt, Erwecker, ich fürchte allerdings, dass der Krieg gerade erst beginnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31216] = { id = 31216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Himmel verfinstert sich", description = "Der Schwarm fängt an, <Erwecker/Erweckerin>! Die Mantis sammeln sich im Herzen der Angst.\n\nSie füllen den Himmel bereits mit ihren Flügeln und zerfetzen die Erde mit ihren Klauen. Sie werden ihren finsteren Marsch erst unterbrechen, wenn ihre Körper offen und blutend auf dem Boden liegen.\n\nUnd das werden wir mit Freuden tun. Wir werden von oben angreifen. Nutzt meine Gifte, um ihre Vorhut zu vernichten, während ich fliege.\n\nAber vermischt die Seren nicht, bis Ihr bereit seid, anzugreifen. Die Reaktion kann recht... heftig sein.\n\nSprecht mit mir, wenn Ihr soweit seid.", sourceObjective = "Tötet 200 Mantis und 3 Kunchong oder grauenhafte Ungetüme, während Ihr mit Xaril dem vergifteten Geist fliegt.", progress = "Diese wunderbare Zerstörung!", completion = "Gut gemacht, Erwecker. Ihr habt die Zielgenauigkeit eines Zerstörers.", sourceObjectiveStatus = "unverified-source-field" }
quests[31220] = { id = 31220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Herausforderers: Falkenmeister Nurong", description = "Ihr verdient Euch immer mehr Respekt bei den Shado-Pan, {name}.\n\nNurong möchte seine Fähigkeiten gegen Euch auf die Probe stellen.\n\nDas Gute daran: Wenn Ihr gewinnt, werde ich ihm erlauben, sich Euch auf Euren Missionen anzuschließen.\n\nDer Haken daran: Ich glaube eigentlich nicht, dass Ihr gegen ihn gewinnen könnt.", sourceObjective = "Fordert Falkenmeister Nurong heraus und besiegt ihn im Kampf in der Shado-Pan-Garnison in der Tonlongsteppe.", progress = "Keine Lust auf diese Herausforderung? Kann ich verstehen.", completion = "Tja... Offenbar habe ich mich getäuscht.\n\nGute Arbeit. Nurong wird Euch fortan gerne auf Euren Missionen begleiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[31221] = { id = 31221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Herausforderers: Tenwu der Rote Rauch", description = "So... Der berüchtigte Tenwu der Rote Rauch hat Euch also herausgefordert.\n\nDiesen Namen hat er sich übrigens selbst gegeben. Er ist ein guter Kämpfer und Schurke. Allerdings muss man sich wundern, wie er sich so gut an seine Gegner anschleichen kann, wo er doch immerzu lautstark prahlt.\n\nAuf jeden Fall solltet Ihr die Herausforderung annehmen. Vielleicht könnt Ihr ihn etwas Demut lehren. Vielleicht auch nicht. Wenn Ihr aber gewinnen könnt, wird er Euch wohl auf Euren Missionen begleiten wollen. \n\nUnd ich darf mich auf gute Unterhaltung freuen.", sourceObjective = "Fordert Tenwu den Roten Rauch heraus und besiegt ihn im Kampf in der Shado-Pan-Garnison in der Tonlongsteppe.", progress = "Und? Wie ist es gelaufen?", completion = "Respekt! Gut gemacht. Eure Kampffähigkeiten sind beachtlich.\n\nVielleicht wird er sich ja in Zukunft darauf konzentrieren, mit Euch mitzuhalten, und endlich seine große Klappe halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[31228] = { id = 31228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prophet Khar'zul", description = "Prophet Khar'zul ist ein mächtiger Zauberer, aber er unterschätzt auch Eure Fähigkeiten.\n\nKhar'zul und seine Streitkräfte müssen vernichtet werden, um dieses Dorf zu beschützen. Sein Tod wird dem Donnerkönig ein deutliches Zeichen setzen, dass wir uns nicht so einfach besiegen lassen!\n\nIhr findet ihn auf der Insel der Abrechnung.", sourceObjective = "Besiegt Prophet Khar'zul.", completion = "Aus diesen Ereignissen sollte man lernen, {name}.\n\nEs ist wichtig, dass wir aus unserer Geschichte Lehren ziehen. Wenn wir der Geschichte Aufmerksamkeit gewidmet hätten, wäre es uns vielleicht möglich gewesen, das hier früher abzuwenden.\n\nAlles Geschehene war bereits vorhergesagt, wir wussten es nur nicht zu deuten.", sourceObjectiveStatus = "unverified-source-field" }
quests[31230] = { id = 31230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen in Morgenblüte", description = "Cho ist unterwegs auf einem seiner Abenteuer und dieses Mal wird ein großer Batzen Jade benötigt. Ich werde wohl ein paar ausstehende Gefallen einlösen.\n\nWie wäre es, wenn Ihr Euch in der Zwischenzeit einigen der Einheimischen vorstellt?\n\nEs wäre gut, Kai Wanderbräu und Meister Windpelz kennenzulernen. Oh, und grüßt Peiji Zapfgold drüben beim Gasthaus von mir.\n\nMit den dreien solltet Ihr schon mal einen guten Eindruck vom Leben in Morgenblüte erhalten.", sourceObjective = "Sprecht mit Kai Wanderbräu, Meister Windpelz und Peiji Zapfgold in Morgenblüte.", progress = "Glück gehabt?", completion = "Gut, gut, gut. Ihr werdet hier richtig gut reinpassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31231] = { id = 31231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Auslöschung der Schreckensspinner", description = "Auf der Terrasse von Gurthan, wo Ihr mich gefunden habt, ziehen Schreckensspinner weiterhin die Aufmerksamkeit der Shado-Pan-Bogenschützen auf sich, die sich sonst darum kümmern könnten, diesen elenden Schwarm zu lichten.\n\nMerzt die Spinnen aus und entlastet die Bogenschützen auf der Mauer.", sourceObjective = "Tötet 8 Schreckensspinnerhüter auf der Terrasse von Gurthan. Bittet Kil'ruk den Windschnitter, Euch dort abzusetzen.", completion = "Ich konnte Spinnen noch nie leiden. Widerliche, stumpfsinnige Insekten.", sourceObjectiveStatus = "unverified-source-field" }
quests[31232] = { id = 31232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein uraltes Reich", description = "Meine Brüder reden von einem uralten Mogureich, das einst in den Ruinen im Osten existierte.\n\nDieser Stamm kannte einst unbeschreibliche Geheimnisse über die Zauberei und Unterwerfung.\n\nIch bin sehr wissbegierig, <Erwecker/Erweckerin>, und möchte mehr über die Reiche herausfinden, die nach meiner Zeit existierten.\n\nDas Wissen über die Vergangenheit bestimmt unsere Zukunft.\n\nSucht in den Ruinen nach ihren alten Tafeln. Ich werde ihre Geheimnisse studieren und sie mir zu eigen machen.", sourceObjective = "Sammelt 8 Gurthanitafeln.", progress = "Welches Wissen bringt Ihr?", completion = "Sehr gut, Erwecker. Diese Tafeln zu entziffern wird Zeit in Anspruch nehmen, doch alles Wissen ist es wert.", sourceObjectiveStatus = "unverified-source-field" }
quests[31233] = { id = 31233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saft anzapfen", description = "Östlich von hier steht ein Wäldchen mit jungen Bernbäumen, <Erwecker/Erweckerin>.\n\nIch habe Zapfvorrichtungen an den Bäumen angebracht, hatte aber zu viel zu tun, um den Saft einzusammeln.\n\nIch brauche jemanden, der die Entsafter findet. Aktiviert sie und bringt mir dann Proben von dem Bern.", sourceObjective = "Sammelt 6 Portionen Bernsaft.", progress = "Diese Bäume sind noch jung. Sie sind noch keine Kypari.\n\nIhr Saft ist wie Wasser, während der Saft eines echten Kyparibaums Wein ähnelt.\n\nSie müssen weiterwachsen.", completion = "Oh ja, genau das habe ich gebraucht.\n\nIch werde diese Proben untersuchen. Wir müssen die Gesundheit dieser jungen Kypari weiter überwachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31234] = { id = 31234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Auge ausstechen", description = "Ah! <Erwecker/Erweckerin>! Ihr müsst mir helfen! (Helft mir, sonst verhelfe ich mir zu Euch!)\n\nIch brauche mehr Material für meine Experimente, oh ja! (Blut und Eingeweide, Herzen und Hirne, Zungen und Augen, Augen, Augen!)\n\nWestlich von hier habe ich Kreaturen aus Nebel und Dunst gesehen. Sie besitzen solch große, runde, wunderbare Kugeln! Groß, um zu sehen, rund und unverwandt!\n\nGeht schon, <kleiner Erwecker/kleine Erweckerin>. Geht und bringt mir ein makelloses Auge!", sourceObjective = "Sammelt 1 makelloses Morastbestienauge.", progress = "Ooooh, welche großartigen, leckeren Teile habt Ihr mir denn gebracht?", completion = "Ja, ja! Wunderbar! Ach, wie köstlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[31235] = { id = 31235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfui, noch mehr Spinnen", description = "Diese Waffe habe ich vor Kurzem bei einem Spähgang in der Nähe der Mauer gefunden. Sie sieht genau richtig aus, um Euren Shado-Pan mit ihrer Plage auf der Terrasse von Gurthan zu helfen.\n\nJe mehr sie sich darauf konzentrieren, die Spinnen von der Mauer fernzuhalten, umso weniger Zeit bleibt ihnen zum Töten verängstigter Schwarmgeborener.", sourceObjective = "Benutzt das Drachengewehr der Shado-Pan, um 20 Schreckensspinnereier auf der Terrasse von Gurthan zu zerstören.", completion = "Eine primitive Waffe, doch sie hat ihre Berechtigung.", sourceObjectiveStatus = "unverified-source-field" }
quests[31237] = { id = 31237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Terrasse von Insekten befreien", description = "Wenn diese Kaiserin tatsächlich von Furcht und Verfolgungswahn befallen ist, hat sie sicherlich Kundschafter in alle Winkel des Landes entsandt, um ihre Kontrolle zu festigen.\n\nDiese Kundschafterlarven sind vermutlich überall, doch schwierig mit bloßem Auge zu entdecken. Über die Pheromonspur, die sie hinterlassen, kann man sie leichter aufspüren.\n\nIch habe Euch bereits ein reaktives Toxin... geschenkt, das Euch vorübergehend, nachdem Ihr den Siegestaumel durchlebt habt, diese Spuren erkennen lässt.\n\nBrecht jetzt zur Terrasse von Gurthan auf und findet diese Spione.", sourceObjective = "Zerstampft 6 Augen der Kaiserin auf der Terrasse von Gurthan. Wenn Ihr etwas tötet, wird Euch die Pheromonfährtensuche bei der Aufstöberung helfen.", completion = "Information ist Macht, {name}. Wir dürfen nicht zulassen, dass die Kaiserin unsere Bewegungen überwacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[31238] = { id = 31238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nahrung fürs Hirn", description = "Kovoks Wachstum ist beschleunigt, möglicherweise kann jedoch sein Gehirn nicht Schritt halten. Er braucht eine spezielle Ernährung, damit er nicht die Kontrolle über seinen eigenen Körper verliert.\n\nMushanzungen sind reich an Nährstoffen, die das Wachsturm von Kunchonggehirnen fördern, doch normalerweise fressen sie die Tiere ganz und werden schnell satt. Wenn wir Kovok etwa alle paar Tage nur mit Mushanzungen füttern, sollte das sein Wachstum ausgleichen.\n\nIn den Hügeln östlich von hier, nicht weit von der Terrasse von Gurthan, grasen Großrückenmushan.", sourceObjective = "Bringt 4 Mushanzungen zu Kaz'tik dem Manipulator in Klaxxi'vess.", progress = "Habt Ihr eine passende Mahlzeit für Kovok gefunden?", completion = "Während Ihr fort wart, hat Kovok die ganze Zeit gewinselt. Es war so richtig herzergreifend.", sourceObjectiveStatus = "unverified-source-field" }
quests[31239] = { id = 31239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Name ist gut, Name Name ist besser!", description = "Du willst also ein Ho-zen sein, hä, Nappel?\n\nHo-zen verteidigen ihr Land vor Feinden, wie Jinyu.\n\nKah Kah hat viele Kämpfe mit Jinyu geschlagen und alle gewonnen.\n\nHo-zen geben nur guten Flotschern zwei Namen. Geh und flotsch Jinyu und vielleicht nennen wir dich {name} {name}.\n\nJinyu kriechen am Fluss rum. Flotsch sie bis es dommelt!", sourceObjective = "Tötet 7 Strandläufer der Jinyu", completion = "Ha ha! Nappel hat verfiddelte Jinyu geflotscht!", sourceObjectiveStatus = "unverified-source-field" }
quests[31240] = { id = 31240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guo-Lai-Befall", description = "Anji war hier und hat nach Euch gefragt. Sagte, sie war auf dem Weg nach Nordosten, in die Ruinen.\n\nOh, Anji ist wirklich ein zorniger Charakter! Ist auf lange Sicht vielleicht besser für Eure Gesundheit, wenn Ihr sie nicht warten lasst.", sourceObjective = "Sprecht mit Anji Herbstlicht in den Guo-Lai-Ruinen.", completion = "Gut, dass Ihr da seid.\n\nIch hatte schon daran gezweifelt, dass Ren Euch die Nachricht gegeben hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[31241] = { id = 31241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiese Nappels", description = "{name} <guter/gute> Nappel, heißt es…\n\n{name} helfen Ho-zen, heißt es…\n\nnicht mehr {name} flotschen, heißt es.\n\nDas in Ordnung. Da drüben gucken. Fiese Nappels fallen runter wie Regen, die kann man flotschen!\n\nGeh und hab Spaß. Aber nicht vergessen, Häuptling Kah Kah kriegt die Schimmerlinge! Das ist Regel von Ho-zen Nummer zwei.\n\n<Jik Jik kratzt sich am Kopf.>\n\nHmm, alle Regeln von Ho-zen sind Nummer zwei...", sourceObjective = "Sammelt 6 Dienstmedaillons der Allianz von kampferprobten Fallschirmjägern.", progress = "Haste was, Nappel?", completion = "Nappelgeflotsche machen Ho-zen reich mit Schimmerlingen!\n\n{name} macht guten zweiten Eindruck. Und für Ho-zen, Nummer Zwei ist am wichtigsten!", sourceObjectiveStatus = "unverified-source-field" }
quests[31242] = { id = 31242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebelhauch", description = "Meine Späher haben zwar heute nichts über Mogu in der Nähe des Dorfes berichtet, dafür aber von Problemen mit den Tieren in der Gegend und Geistern am Friedhof. Ich habe Che entsandt, um die Situation zu evaluieren, aber er wird sicher Eure Hilfe brauchen.\n\nBitte begebt Euch nach Südwesten in das Dorf und trefft dort Che. Bietet ihm jede erdenkliche Hilfe an.", sourceObjective = "Sprecht mit Che Wildmarsch in Nebelhauch.", completion = "Da hat Leven mir eine echte Hilfe geschickt. Dafür werde ich mich später bei ihm bedanken.", sourceObjectiveStatus = "unverified-source-field" }
quests[31243] = { id = 31243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Nebelhauch", description = "In Nebelhauch, im Südwesten, sind Mogu gesichtet worden. Ich habe schon Rook und Sun entsandt, aber ich brauche dort noch jemanden mit Fähigkeiten wie Euren.\n\nBitte macht Euch sofort auf den Weg. Die Dorfbewohner brauchen Eure Hilfe.", sourceObjective = "Sprecht mit Sun Zartherz in Nebelhauch.", completion = "Den Himmlischen sei Dank, dass Ihr das seid! Es ist alles noch viel schlimmer als angenommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31244] = { id = 31244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guo-Lai-Lager", description = "Leven war ganz schön sauer und sagte etwas über Mogu in den Ruinen.\n\nIhr solltet ihn am besten suchen. Leven ist nicht witzig, wenn er sauer ist.", sourceObjective = "Sprecht mit Leven Morgenklinge in den Guo-Lai-Ruinen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31245] = { id = 31245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebelhauch", description = "Che hat auf seinem Weg ins Dorf nach Euch gefragt, aber ich sagte ihm, ich hätte Euch nicht gesehen.\n\nWenn Ihr also wollt, könnt Ihr ihn jetzt aufsuchen. Aber auf diese Weise müsst Ihr Euch nicht verpflichtet fühlen! Das war doch klug bedacht von mir, nicht wahr?", sourceObjective = "Sprecht mit Che Wildmarsch in Nebelhauch.", completion = "Ren hat Euch Bescheid gesagt? Er scheint immer so unbekümmert, aber er macht das Richtige, wenn es darauf ankommt. Da kann man ihm keinen Vorwurf machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31246] = { id = 31246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Nebelhauch", description = "Ich sehe Rauch aus dem Dorf aufsteigen. Und dieses Mal ist es nicht meine Schuld!\n\nIhr solltet Euch dorthin aufmachen und Eure Hilfe anbieten.", sourceObjective = "Sprecht mit Rook Steinzeh in Nebelhauch.", completion = "Ihr seid hier und wollt Rook helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31247] = { id = 31247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Garnison der Untergehenden Sonne", description = "Anji und Kun haben hier auf dem Weg zur Garnison Rast gemacht. Ein hübsches Paar, findet Ihr nicht? So verschieden und doch so innig miteinander... Ah, wenn ich nur daran denke, geht mir das Herz auf.\n\nSie haben übrigens nach Euch gefragt. Vielleicht wollen sie ja, dass Ihr an ein paar Ausbildungseinheiten teilnehmt? Jedenfalls hoffe ich, dass sie nichts Unanständiges mit Euch vorhaben...", sourceObjective = "Sprecht mit Anji Herbstlicht in der Garnison der Untergehenden Sonne.", completion = "Ihr kommt gerade rechtzeitig. Ich wollte soeben mit ein paar Rekruten ein paar Ausbildungseinheiten durchgehen. Aber eigentlich interessiert es mich viel mehr, was Ihr zu bieten habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31248] = { id = 31248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Guo-Lai-Ruinen", description = "Ich habe Anji und Kun aufgetragen, die Erkundung der Guo-Lai-Ruinen fortzusetzen. Wir haben zwar heute keine Meldungen über die Anwesenheit von Mogu dort erhalten. Aber dennoch scheinen die Ruinen zu den Orten hier im Tal zu zählen, denen ihr größtes Interesse gilt. Vor dem Hintergrund des Angriffs auf das Gebiet am See habe ich die beiden dort auf Patrouille geschickt.\n\nUnd ich möchte, dass Ihr Euch ebenfalls dort einfindet.\n\nBegebt Euch in Richtung Westen am See vorbei bis zu den Ruinen. Anji wird Euch dort weitere Anweisungen geben können.", sourceObjective = "Sprecht mit Anji Herbstlicht bei den Guo-Lai-Ruinen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31249] = { id = 31249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebelhauch", description = "Nach allem, was ich gehört habe, ist das Dorf nicht von der Shao-Tien-Offensive betroffen, aber ich möchte kein Risiko eingehen.\n\nIch werde Euch und Che Wildmarsch aussenden, um im Dorf nach dem Rechten zu schauen und den Dorfbewohnern Hilfe anzubieten.", sourceObjective = "Sprecht mit Che Wildmarsch in Nebelhauch.", completion = "Ein seltsames Gefühl, vom Kampf abgezogen zu werden. Aber Leven hat recht: Die Dorfbewohner brauchen unseren Schutz. Wir dürfen keine Risiken eingehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31251] = { id = 31251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besser essen geht nicht!", description = "Ja, ja.\n\nJeder weiß, dass wir Goblins herumbasteln. Und Sprengstoff machen. Und... Nun, Ihr wisst ja bestimmt auch von den unrühmlichen Sachen.\n\nWas aber niemand weiß, ist, dass ich hervorragend kochen kann! Das ist ein Hobby von mir.\n\nBesorgt uns ein paar leckere Stücke Fleisch von den Tieren aus dieser Gegend, und ich werde uns die besten Mahlzeiten zubereiten, die es ÜBERHAUPT gibt!\n\nUnd ich verspreche auch, nur drei oder vier Prozent Raketentreibstoff zu verwenden.", sourceObjective = "Besorgt 160 Kun-Lai-Fleischbrocken.", progress = "Die Fleischbrocken, {name}? Wir brauchen sie!", completion = "Ihr wisst, was man über's Kochen sagt - LFG. Lecker, frisch... und... Geschirr?", sourceObjectiveStatus = "unverified-source-field" }
quests[31252] = { id = 31252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zur Westwindruhestätte", description = "Nun, so wie ich die Sache sehe, haben wir viel wiederaufzubauen.\n\nIch bin niemand, der sich einer großen Sache anschließt, aber meine Landarbeiter werden hier nicht viel zu tun haben, um ehrlich zu sein. Und da Ihr ihnen geholfen habt, wollen sie sich Eurer \"Allianz\" anschließen. Warum sollte ich sie also aufhalten?\n\nNehmt sie mit zu Landarbeiter Bo. Sie werden mir zwar fehlen, aber bei Euch sind sie besser aufgehoben.", sourceObjective = "Kehrt zu Landarbeiter Bo in der Westwindruhestätte am Kun-Lai-Gipfel zurück.", completion = "Es war das Richtige, diese Jungs mitzubringen. Wir lassen sie für Euch in null Komma nichts etwas zu essen anpflanzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[31253] = { id = 31253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zur Ostwindruhestätte", description = "Nun, so wie ich die Sache sehe, haben wir viel wiederaufzubauen.\n\nIch bin niemand, der sich einer großen Sache anschließt, aber meine Landarbeiter werden hier nicht viel zu tun haben, um ehrlich zu sein. Und da Ihr ihnen geholfen habt, wollen sie sich Eurer \"Horde\" anschließen. Warum sollte ich sie also aufhalten?\n\nNehmt sie mit zu Landarbeiter Ko. Sie werden mir zwar fehlen, aber bei Euch sind sie besser aufgehoben.", sourceObjective = "Kehrt zu Landarbeiter Ko in der Ostwindruhestätte am Kun-Lai-Gipfel zurück.", completion = "Es war das Richtige, diese Jungs mitzubringen. Wir lassen sie für Euch in null Komma nichts etwas zu essen anpflanzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[31254] = { id = 31254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Straße nach Kun-Lai", description = "Ah! Seid gegrüßt, Freund von Lehrensucher Cho. Ich habe eine Nachricht für Euch.\n\n<Die merkwürdige kleine Kreatur reicht Euch einen ramponierten Schriftrollenbehälter.>\n\nDer Lehrensucher erwartet Euch in Kun-Lai. Die Reise dorthin ist äußerst gefährlich, oh ja, äußerst gefährlich.\n\nLasst Euch von den Ortskundigen helfen, denen Ihr auf Eurem Weg begegnet.", sourceObjective = "Reist über die Verhüllte Treppe nach Binan.", progress = "Noch mehr Fremde? Dieser Tag bringt mich an meine Grenzen.", completion = "Oh, Ihr seid ein Freund von Cho? Willkommen! Willkommen!\n\nIch würde Euch ein Bankett auftischen, aber wie Ihr sehen könnt, stecken wir momentan in großen Schwierigkeiten.\n\nWürdet Ihr uns vielleicht helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31255] = { id = 31255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Straße nach Kun-Lai", description = "Ah! Seid gegrüßt, <Freund/Freundin> von Lehrensucher Cho. Ich habe eine Nachricht für Euch.\n\n<Die merkwürdige kleine Kreatur reicht Euch einen ramponierten Schriftrollenbehälter.>\n\nDer Lehrensucher erwartet Euch in Kun-Lai. Die Reise dorthin ist äußerst gefährlich, oh ja, äußerst gefährlich.\n\nLasst Euch von den Ortskundigen helfen, denen Ihr auf Eurem Weg begegnet.", sourceObjective = "Reist über die Verhüllte Treppe nach Binan.", progress = "Noch mehr Fremde? Dieser Tag bringt mich an meine Grenzen.", completion = "Oh, Ihr seid ein Freund von Cho? Willkommen! Willkommen!\n\nIch würde Euch ein Bankett auftischen, aber wie Ihr sehen könnt, stecken wir momentan in großen Schwierigkeiten.\n\nWürdet Ihr uns vielleicht helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31256] = { id = 31256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treibt sie zusammen", description = "Lok'tar, {class}.\n\nWir haben Fortschritte gemacht, aber wir müssen beweglich sein, wenn wir uns hier am Kun-Lai behaupten wollen.\n\nIch sehe nicht viele Worgs, Kodos oder dergleichen in dieser Gegend. Was ich aber sehe, sind Yaks. Unsere Pandarenverbündete haben gesagt, dass sie gute Reittiere abgeben, also nehmen wir halt die.\n\nZieht los, treibt ein paar zusammen und bringt sie hierher, damit unsere Leute auf ihnen reiten können!", sourceObjective = "Treibt 3 Yaks der Wilden Ebenen zusammen und bringt sie zur Ostwindruhestätte.", completion = "Gut gemacht! Nun, ich muss schon sagen, sie sind ziemlich störrisch. Aber sie sollten ausreichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31260] = { id = 31260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meisterprofiteur: Casheen", description = "Ich hab' da eine geniale Idee für eine neue Gaunerei!\n\nBei meinem letzten Flug sah ich eine unglaublich alte Tigerin umherstreifen.\n\nWisst Ihr, was für einen Preis ihr Blut auf dem Schwarzmarkt erzielen würde? Und wenn ich dann noch ein paar Hexenmeistern erzähle, dass das Blut ihren Beschwörungszaubern zusätzliche Kraft verleiht...\n\nAlso wenn Ihr mir etwas von ihrem Blut bringt, beteilige ich Euch an der Gaunerei. Zuletzt habe ich die Tigerin auf der anderen Seite des Dojani gesehen.", sourceObjective = "Sammelt das Blut der alten Tigerin.", progress = "Ich hatte mir ja schon überlegt, es selbst mit dieser Tigerin aufzunehmen, aber ich hänge zu sehr an meinem Leben, um ehrlich zu sein...", completion = "Beeindruckend! Riecht Ihr schon das Geld? Hier ist Euer Anteil.", sourceObjectiveStatus = "unverified-source-field" }
quests[31261] = { id = 31261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitän Jack ist tot", description = "Halb geronnenes Blut tropft aus Kapitän Jacks Kopf auf den Boden und versiegt dort, als Ihr Eure hart erkämpfte Trophäe begutachtet.\n\nSeltsam, aber Ihr habt jetzt keine Zeit, das zu untersuchen. Zu viel Arbeit muss erledigt werden.\n\nDer Häuptling Eurer neuen Freunde wird sicherlich beeindruckt sein von diesem Beweis Eurer Flotschfähigkeiten.", sourceObjective = "Bringt Kapitän Jacks Kopf zu Häuptling Kah Kah in Flotschhügel.\n\nBereitgestellter Gegenstand:", completion = "Verfiddelter Flotsch, Nappel!", sourceObjectiveStatus = "unverified-source-field" }
quests[31262] = { id = 31262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kranichbeherrschung: Dolchschnabel", description = "Nun, da Ihr ein Gespür für den Kampfstil des Kranichs entwickelt habt, werdet Ihr es mit einem echten Prachtexemplar zu tun bekommen.\n\nDolchschnabel!\n\nZumindest nenne ich den Burschen so. Ist der größte Kranich, den ich je gesehen habe. Und sein Schnabel ist messerscharf.\n\nNordwestlich von hier befindet sich ein großer Wasserfall, aus dem der Dojani entspringt. Dolchschnabel hält sich meistens in der Nähe dieses Wasserfalls auf.\n\nWenn Ihr mir seinen Schnabel als Trophäe bringt, lege ich bei Nesingwary ein gutes Wort für Euch ein.", sourceObjective = "Holt Euch den Dolchschnabel.", progress = "Ich habe gesehen, wie dieser Vogel einem Tiger das Gesicht durchbohrt hat. Wo bitteschön sind wir hier, wenn Tiger zur Beute von Vögeln werden?", completion = "Na DAS nenne ich mal eine Trophäe. Sieht ziemlich einschüchternd aus. Moment... klebt da etwa Euer Blut dran?", sourceObjectiveStatus = "unverified-source-field" }
quests[31265] = { id = 31265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mazus Atem", description = "Ihr seid also hier, um zu helfen, ja? Na, eins nach dem anderen.\n\n<Arie durchwühlt kurz ihre Taschen und bringt eine kleine Phiole mit einer leuchtenden blauen Flüssigkeit zum Vorschein.>\n\nHier ist es! \"Mazus Atem\". Nach einer Rezeptur des Käpt'n.\n\nWas? Ihr dachtet, ich würde Euch ohne Atemhilfe auf See schicken? Ich brauche Deckhelfer, keine Leichen!\n\nRunter damit, Grünschnabel. Damit habt Ihr dort draußen auf dem Riff eine reelle Chance.", sourceObjective = "Trinkt den Trank aus Mazus Atem.", progress = "Nein, ich habe nichts zum Runterspülen. Trinkt einfach aus!", completion = "Ihr werdet mir noch danken.", sourceObjectiveStatus = "unverified-source-field" }
quests[31266] = { id = 31266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfall der Mogu", description = "Wir haben Berichte über mehrere Mogugruppen erhalten, die hier in Tonlong an der Küste eingefallen sind. Ich habe keine Ahnung, was sie hier tun, und ganz ehrlich: Es ist mir auch egal.\n\nIhr habt Euch bewiesen, daher wollen wir Euch diese Mission anvertrauen.\n\nFolgendes wird passieren: Ihr zieht los, findet sie und tötet sie alle.\n\nUnsere Späher haben gemeldet, dass die erste Gruppe Richtung Norden gelandet ist, zwischen hier und dem Plateau des Totensprechers. Geht dorthin und schaltet sie aus.", sourceObjective = "Findet und tötet den Spionagemeister der Shan'ze.", progress = "Warum sind sie noch nicht tot?", completion = "Es war nur eine Ablenkung! Sie machen sich bereit, den Niuzaotempel anzugreifen!", sourceObjectiveStatus = "unverified-source-field" }
quests[31267] = { id = 31267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vernichtung der Nebelklingen", description = "Korven hat mir erzählt, was er herausgefunden hat. Auf dem Grund des Sternensees gibt es eine gewaltige Bernablagerung.\n\nLeider lebt am Ufer des Sees ein feindseliger Saurokstamm, der den Bern als sein Eigentum betrachtet.\n\nSeine Angehörigen werden uns nicht einfach so in ihr Gebiet vordringen lassen.\n\nBegebt Euch nach Süden zum See. Tötet die Nebelklingensaurok, damit wir den Bern in der Nähe leichter abtragen können.", sourceObjective = "Tötet 6 Reißer der Nebelklingen.", completion = "Gut gemacht. Mit diesem Bern können wir Waffen für unsere Sache fertigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31268] = { id = 31268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleine, graue Zellen", description = "Tief im Süden brütet der Schwarm Vernichtungswaffen aus - riesige Bernskorpione, die so gut wie unzerstörbar sind.\n\nWie alle anderen Kreaturen sind auch sie manipulierbar, im Gegensatz zu anderen Kreaturen haben sie sich aber noch nicht meiner Gedankenkontrolle unterworfen.\n\nWie es scheint, muss ich weitere Forschungen betreiben, ehe es mir gelingt, sie für unsere Zwecke zu beherrschen.\n\nIch muss ihre Gehirne untersuchen, und Eure Aufgabe ist es, mir ein paar Exemplare zu besorgen.\n\nNehmt diesen Schallemitter. Er hat sich als ziemlich wirksam gegen die Biester erwiesen.", sourceObjective = "Sammelt 3 bernverkrustete Gehirne von Bernstechern der Ik'thik.", progress = "Sie widersetzen sich weiterhin meiner Schallmanipulation. Ich muss herausfinden, weshalb.", completion = "Sieh mal einer an, wie interessant. Sie sind anders als alle anderen Gehirne, die ich gesehen habe.\n\nIch werde sie genau untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31269] = { id = 31269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schuppenlord", description = "Die Saurok am Sternensee empfangen ihre Befehle von ihrem Schuppenlord, einem grausamen, gnadenlosen Anführer, der sein Revier erbittert bewacht.\n\nWenn es uns gelingt, diesen Anführer auszuschalten, erhalten wir Zugriff auf die gewaltige Bernader unter dem See.\n\nGeht. Ihr Anführer erteilt seine Befehle von seinem unterirdischen Sitz am südlichen Seeufer aus.", sourceObjective = "Tötet den Schuppenlord der Nebelklingen.", progress = "Ist es vollbracht?", completion = "Gut. Freut mich zu hören, dass er tot ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[31270] = { id = 31270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kampf gegen die Angst", description = "Als wir den Einfluss des Sha bei Kypari Zar bemerkten, hatte ich gehofft, die Verderbnis könnte noch geläutert werden.\n\nLeider hat der Rat der Klaxxi bestätigt, dass die Verderbnis des Sha der Angst tief verwurzelt ist und sich weiter ausbreitet.\n\nIm Süden habe ich beobachtet, wie ein Teil der heimischen Tier-und Pflanzenwelt von einem namenlosen Schrecken ergriffen wurde.\n\nDas Sha kann seine Opfer zu furchtbar abscheulichen Kreaturen verzerren.\n\nWir müssen der Verderbnis Einhalt gebieten, bevor sie noch schlimmer wird. Sucht die Sha-verseuchten Schreckensschuppenskorpide. Vernichtet sie.", sourceObjective = "Tötet 15 Schreckensschuppenskorpide.", completion = "Ihr habt die Hügel von den verseuchten Kreaturen befreit? Gut.\n\nDas Sha ist ein gnadenloser Gegner. Also dürfen auch wir ihm keine Gnade zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31271] = { id = 31271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlechte Gene", description = "Tief im Süden, <Erwecker/Erweckerin>, führen die Genomanten der Kaiserin ihre finsteren Experimente durch. (Finster, mag schon sein, aber nicht so finster wie meine!)\n\nSie sezieren und verändern die wilden Tiere der Umgebung und erzeugen Kreaturen nach eigenem Gutdünken. (Ihre Entwürfe werden bald meine Entwürfe sein!)\n\nDas dürfen wir nicht zulassen! (Nein, nein! Solche Macht steht nur mir zu!)\n\nIhre Mutationen werden bereits im Krieg eingesetzt. Geht los! Zerstört sie um jeden Preis!", sourceObjective = "Tötet 3 Genomanten der Ik'thik und 6 Eierdrohnen der Ik'thik.", completion = "Ja, ja! Sie sind tot!\n\nDanke, Erwecker. Das habt Ihr gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[31272] = { id = 31272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ansteckung", description = "Die Genomanten der Kaiserin spielen mit gefährlichen Spielzeugen.\n\nWeiter im Süden injizieren sie den hiesigen Tieren pheromonhaltige Parasiten, um monströse Mutationen für den Krieg zu erschaffen.\n\nSie waren so nachlässig, dass ihre parasitären Würmer in das örtliche Ökosystem entkommen konnten.\n\nWenn nichts dagegen unternommen wird, breitet sich die Infektion so lange von Tier zu Tier aus, bis wir es mit einer Seuche zu tun haben.\n\nIch werde Euch ein schwaches Toxin injizieren, mit dem Ihr in der Lage sein werdet, angesteckte Kreaturen zu identifizieren.\n\nTötet die Träger auf der Stelle.", sourceObjective = "Tötet 6 infizierte Wildtiere. Infizierte Wildtiere sind Knochenstaubmotten, Blauhautmushan und mutierende Skorpide.", completion = "Die Infektion hatte sich also schon ausgebreitet. Wie es scheint, konntet Ihr die Verbreitung gerade noch stoppen.\n\nIch glaube nicht, dass die Genomanten ihre haarsträubenden Experimente einstellen werden, wir müssen ihre Anstrengungen jedoch weiter vereiteln.", sourceObjectiveStatus = "unverified-source-field" }
quests[31274] = { id = 31274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raid Finder (1st)" }
quests[31275] = { id = 31275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raid Finder (Nth)" }
quests[31277] = { id = 31277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überraschungsangriff!", description = "Diese abscheulichen Mogu...\n\nDie Späher waren nur ein Ablenkungsmanöver! Während wir ihre Spione jagten, griff ihre Hauptstreitmacht den Niuzaotempel an. Verderbte Schlangen, überall Mogu... das ist eine Katastrophe!\n\nGlücklicherweise konnte Ban ihre Linien mit den Elitemitgliedern unseres Ordens durchdringen. Wenn dieses Kunststück auch Euch gelingt, stoßt zu ihm. Wir müssen dem ein Ende setzen!", sourceObjective = "Trefft Euch mit Ban Bärenherz am Niuzaotempel in der Tonlongsteppe und setzt der dortigen Moguinvasion ein Ende.", completion = "Niuzao ist gerettet. Die Mogu wurden zurückgeschlagen. Und Ihr, mein Freund, Ihr habt Euch einer großen Ehre als würdig erwiesen. \nWir werden Euch in die Reihen der Shado-Pan aufnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31278] = { id = 31278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anleitung zur Questerstellung", description = "Juchu! Ihr dürft eine Schnitzeljagdquest erstellen! Findet heraus, was als Nächstes zu tun ist.", sourceObjective = "Erstellt eine Schnitzeljagdquest.", sourceObjectiveStatus = "unverified-source-field" }
